window.PHILO_BANQUE={"version":2,"updated":"2026-10-16","legacyIds":{"platon-persuasion":"platon-convaincre-sans-faire-connaitre","platon-recherche":"platon-apprendre-et-se-ressouvenir","platon-ecriture":"platon-le-silence-de-lecrit","platon-caverne":null,"platon-desir":null,"aristote-bonheur":"aristote-le-bonheur-et-le-loisir","aristote-vertu":"aristote-devenir-juste","aristote-savoir":"aristote-connaitre-la-cause","aristote-discours":null,"aristote-cite":"aristote-lanimal-politique","aristote-art":"aristote-imiter-pour-apprendre","nietzsche-valeurs":"nietzsche-le-ressentiment-et-les-valeurs","nietzsche-verite":"nietzsche-lhypothese-scientifique","nietzsche-perspective":null,"nietzsche-liberte":"nietzsche-se-liberer-et-creer"},"entries":[{"id":"platon-savoir-et-croire","code":"P01","author":"Platon","title":"Savoir et croire","work":"Gorgias","locator":"454d","quote":"Savoir et croyance ne sont donc pas la même chose, c’est évident.","notions":["verite","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Être certain d’une idée suffit-il pour la connaître ?"},{"function":"L’affirmation","sentence":"Socrate distingue le fait de croire une proposition et le fait de savoir qu’elle est vraie."},{"function":"Les concepts","sentence":"La croyance est une adhésion qui peut être vraie ou fausse, tandis que le savoir ne peut pas être faux sans cesser d’être un savoir."},{"function":"La raison","sentence":"C’est pourquoi la force de notre conviction ne permet pas, à elle seule, de distinguer la croyance du savoir."},{"function":"L’exemple","sentence":"Un accusateur peut croire sincèrement un homme coupable alors que l’enquête établit son innocence."},{"function":"La portée","sentence":"Il faut donc examiner ce qui justifie une affirmation, sans conclure que toute croyance serait nécessairement fausse."}],"uses":[{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Introduire une distinction","reason":"Distinguer l’adhésion à une proposition de la possession de ses raisons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Être conscient, est-ce savoir ?","function":"Limiter une première réponse","reason":"Être convaincu de quelque chose ne garantit pas qu’on le connaisse.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"speaker":"Socrate"},{"id":"platon-convaincre-sans-faire-connaitre","code":"P02","author":"Platon","title":"Convaincre sans faire connaître","work":"Gorgias","locator":"454e–455a","quote":"La rhétorique est donc, semble-t-il, productrice de conviction ; elle fait croire que le juste et l’injuste sont ceci et cela, mais elle ne les fait pas connaître.","notions":["langage","justice","verite"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Un discours qui convainc fait-il nécessairement connaître la vérité ?"},{"function":"L’affirmation","sentence":"Socrate affirme que la rhétorique peut faire adopter un jugement sur le juste sans en donner la connaissance."},{"function":"Les concepts","sentence":"Produire une conviction signifie obtenir l’accord de l’auditeur, tandis que faire connaître exige de lui permettre de comprendre pourquoi le jugement est vrai."},{"function":"La raison","sentence":"Dans une assemblée ou un tribunal, l’orateur peut emporter cet accord sans transmettre un savoir à chacun de ceux qui l’écoutent."},{"function":"L’exemple","sentence":"Un jury ému par un plaidoyer peut ainsi approuver une conclusion sans avoir examiné ce qui la justifie."},{"function":"La portée","sentence":"L’efficacité d’une parole ne garantit donc pas sa vérité, même si une parole vraie peut aussi chercher à convaincre."}],"uses":[{"subject":"Bien parler, est-ce bien penser ?","function":"Contester une assimilation","reason":"L’efficacité persuasive ne prouve pas la justesse de la pensée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Comment savoir ce qui est juste ?","function":"Écarter un faux critère","reason":"L’accord produit par un orateur n’établit pas le savoir du juste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}],"speaker":"Socrate"},{"id":"platon-subir-ou-commettre-linjustice","code":"P03","author":"Platon","title":"Subir ou commettre l’injustice","work":"Gorgias","locator":"469c","quote":"Mais, s’il était nécessaire soit de commettre l’injustice soit de la subir, je choisirais de la subir plutôt que de la commettre.","notions":["justice","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Faut-il préserver sa sécurité au prix d’une injustice ?"},{"function":"L’affirmation","sentence":"Socrate affirme que, s’il devait choisir, il préférerait subir l’injustice plutôt que la commettre."},{"function":"Les concepts","sentence":"Subir l’injustice signifie être victime d’un tort, tandis que la commettre signifie devenir responsable d’une action injuste."},{"function":"La raison","sentence":"Il juge ce second mal plus grave parce qu’il abîme la qualité morale de celui qui agit, au lieu de seulement lui infliger un dommage extérieur."},{"function":"L’exemple","sentence":"Accuser un innocent pour éviter soi-même une peine préserverait peut-être notre sécurité, mais nous rendrait responsables de sa condamnation."},{"function":"La portée","sentence":"La justice de notre conduite vaut donc davantage que l’évitement de toute souffrance, sans que cela oblige à rechercher le malheur."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Fixer une limite morale","reason":"La préservation de soi ne justifie pas n’importe quelle action.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Soutenir une réponse négative","reason":"Souffrir ne rend pas juste l’injustice que l’on commet.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-justice-et-bonheur","code":"P04","author":"Platon","title":"Justice et bonheur","work":"Gorgias","locator":"470e","quote":"J’affirme que l’être (homme ou femme) doté d’une bonne nature morale est heureux, mais que l’être injuste et méchant est malheureux.","notions":["bonheur","justice"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":"Monique Canto (attribution de la traduction GF rappelée dans le recueil Aristote, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"La puissance et la réussite suffisent-elles pour être heureux ?"},{"function":"L’affirmation","sentence":"Socrate soutient qu’une personne juste est heureuse et qu’une personne injuste est malheureuse."},{"function":"Les concepts","sentence":"Il rapporte ainsi le bonheur à la manière dont une personne conduit sa vie, plutôt qu’à la seule quantité de biens dont elle dispose."},{"function":"La raison","sentence":"Une conduite injuste laisse les désirs et les rapports de force gouverner la vie, au lieu de les régler selon ce qui est bon."},{"function":"L’exemple","sentence":"Un dirigeant capable de faire tout ce qui lui plaît peut encore vivre dans la crainte, l’avidité et le désordre."},{"function":"La portée","sentence":"Le succès extérieur ne prouve donc pas le bonheur, mais le lien affirmé entre justice et bonheur demande encore à être défendu."}],"uses":[{"subject":"L’homme injuste peut-il être heureux ?","function":"Défendre une réponse négative","reason":"Distinguer les avantages de l’injuste et le bien de son âme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"La morale peut-elle se définir comme l’art d’être heureux ?","function":"Construire une réponse affirmative","reason":"La justice peut être comprise comme une condition du bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=115","sourceLabel":"Recueil académique · p. 115"}],"speaker":"Socrate"},{"id":"platon-linjustice-ne-justifie-pas-linjustice","code":"P05","author":"Platon","title":"L’injustice ne justifie pas l’injustice","work":"Criton","locator":"49b","quote":"Il s’ensuit que même à l’injustice il ne faut en aucune façon répondre par l’injustice, comme se l’imaginent les gens, dès lors que l’on admet qu’il ne faut jamais commettre l’injustice.","notions":["justice","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une injustice subie rend-elle juste notre vengeance ?"},{"function":"L’affirmation","sentence":"Socrate refuse de répondre à l’injustice par une autre injustice."},{"function":"Les concepts","sentence":"L’injustice désigne ici le tort que l’on fait à autrui, même lorsque cet autre nous a d’abord nui."},{"function":"La raison","sentence":"Si faire injustement du tort est mauvais, le tort subi ne suffit pas à changer la valeur de l’action par laquelle nous ripostons."},{"function":"L’exemple","sentence":"Être victime d’un mensonge n’autorise pas à fabriquer à son tour une fausse accusation."},{"function":"La portée","sentence":"La riposte doit donc rester juste, ce qui permet de distinguer la sanction d’une faute et la vengeance qui reproduit cette faute."}],"uses":[{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Réfuter une justification","reason":"La situation de victime ne supprime pas l’exigence de justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"Ressentir l’injustice m’apprend-il ce qui est juste ?","function":"Limiter le sentiment comme critère","reason":"Le sentiment d’avoir subi un tort peut encore conduire à faire du tort.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-une-opinion-vraie-peut-guider","code":"P06","author":"Platon","title":"Une opinion vraie peut guider","work":"Ménon","locator":"97b","quote":"Donc, une opinion vraie n’est pas un moins bon guide, pour la rectitude de l’action, que la raison.","notions":["raison","verite","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Faut-il toujours savoir pourquoi une action est correcte pour agir correctement ?"},{"function":"L’affirmation","sentence":"Socrate reconnaît qu’une opinion vraie peut guider une action aussi bien qu’un savoir."},{"function":"Les concepts","sentence":"L’opinion vraie atteint le vrai sans nécessairement pouvoir le justifier, alors que le savoir en possède les raisons."},{"function":"La raison","sentence":"Pour arriver au bon résultat, la vérité de l’indication peut suffire, même lorsque celui qui la donne ne sait pas l’expliquer."},{"function":"L’exemple","sentence":"Dans le dialogue, quelqu’un qui a une opinion vraie du chemin de Larissa peut guider les voyageurs aussi bien que celui qui connaît ce chemin."},{"function":"La portée","sentence":"L’efficacité pratique ne permet donc pas de confondre opinion et savoir, car une opinion vraie reste plus fragile qu’une connaissance justifiée."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Nuancer la nécessité du savoir","reason":"Une action correcte peut être guidée par une opinion vraie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Distinguer vérité et justification","reason":"Une croyance peut être vraie sans que son détenteur sache en rendre raison.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}],"speaker":"Socrate"},{"id":"platon-apprendre-et-se-ressouvenir","code":"P07","author":"Platon","title":"Apprendre et se ressouvenir","work":"Ménon","locator":"81d","quote":"Ainsi, le fait de chercher et le fait d’apprendre sont, au total, une réminiscence.","notions":["raison","science"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment chercher une connaissance que l’on ne possède pas encore ?"},{"function":"L’affirmation","sentence":"Socrate propose de comprendre la recherche et l’apprentissage comme une réminiscence."},{"function":"Les concepts","sentence":"La réminiscence est le retour à une connaissance que l’âme aurait acquise avant sa vie présente."},{"function":"La raison","sentence":"Cette hypothèse permet d’expliquer comment une réponse peut être reconnue comme vraie sans avoir été simplement reçue d’un maître."},{"function":"L’exemple","sentence":"L’interrogation du jeune serviteur dans le Ménon fait apparaître une réponse géométrique à travers ses erreurs et ses rectifications."},{"function":"La portée","sentence":"Apprendre serait donc retrouver par l’examen, mais l’expérience du dialogue ne prouve pas à elle seule l’existence antérieure de l’âme."}],"uses":[{"subject":"D’où viennent nos connaissances ?","function":"Proposer une origine du savoir","reason":"La réminiscence fait dépendre l’apprentissage d’un savoir antérieur de l’âme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"},{"subject":"Être conscient, est-ce savoir ?","function":"Distinguer possession et accès","reason":"Une connaissance supposée présente dans l’âme peut encore demander à être retrouvée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}],"speaker":"Socrate"},{"id":"platon-pourquoi-les-hommes-sassocient","code":"P08","author":"Platon","title":"Pourquoi les hommes s’associent","work":"La République","locator":"II, 369c","quote":"Dès lors, un homme recourt à un autre pour un besoin particulier, puis à un autre en fonction de tel autre besoin, et parce qu’ils manquent d’une multitude de choses, les hommes se rassemblent nombreux au sein d’une même fondation, s’associant pour s’entraider.","notions":["etat","travail"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Pourquoi les hommes ne vivent-ils pas chacun de leur côté ?"},{"function":"L’affirmation","sentence":"Socrate explique leur association par la diversité de leurs besoins et leur incapacité à les satisfaire seuls."},{"function":"Les concepts","sentence":"L’entraide consiste à recevoir d’autrui ce que l’on ne peut produire soi-même et à lui apporter en retour une autre contribution."},{"function":"La raison","sentence":"Comme chacun manque de plusieurs choses, la coopération et la répartition des activités rendent la vie commune avantageuse."},{"function":"L’exemple","sentence":"Le cultivateur peut fournir la nourriture tandis que le bâtisseur construit les logements dont tous ont besoin."},{"function":"La portée","sentence":"Les besoins expliquent donc une raison de vivre ensemble, sans suffire à déterminer ce qui rend cette communauté juste."}],"uses":[{"subject":"Est-ce la faiblesse qui nous pousse à vivre en société ?","function":"Installer une première réponse","reason":"L’insuffisance de chacun explique le recours à la coopération.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=126","sourceLabel":"Recueil académique · p. 126"},{"subject":"Les hommes ne vivent-ils en société que par intérêt ?","function":"Donner sa part de vérité à l’intérêt","reason":"L’entraide répond aux besoins ; il reste à examiner si elle épuise le sens de la société.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=126","sourceLabel":"Recueil académique · p. 126"}],"speaker":"Socrate"},{"id":"platon-la-justice-et-les-fonctions","code":"P09","author":"Platon","title":"La justice et les fonctions","work":"La République","locator":"IV, 433b","quote":"Et nous avons dit, de plus, que la justice consiste à s’occuper de ses tâches propres et à ne pas se disperser dans des tâches diverses, et cela, nous l’avons souvent entendu dire de plusieurs autres et nous-mêmes l’avons affirmé à plusieurs reprises.","notions":["justice","etat"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Qu’est-ce qui rend juste l’organisation d’une cité ?"},{"function":"L’affirmation","sentence":"Socrate propose que chacun y accomplisse la tâche qui lui revient sans empiéter sur celles des autres."},{"function":"Les concepts","sentence":"La justice est alors un ordre des fonctions, et non seulement le respect de règles dans les échanges entre personnes."},{"function":"La raison","sentence":"La cité fonctionne comme un ensemble dont chaque activité contribue au bien commun lorsqu’elle tient sa place."},{"function":"L’exemple","sentence":"Les gardiens doivent ainsi protéger la cité plutôt qu’utiliser leur pouvoir pour s’approprier le travail des autres."},{"function":"La portée","sentence":"Cette conception exige un accord entre les fonctions, mais laisse à examiner la justice de leur répartition et la possibilité d’en changer."}],"uses":[{"subject":"Comment savoir ce qui est juste ?","function":"Proposer un critère à examiner","reason":"Définir le juste par l’organisation et la répartition des fonctions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"},{"subject":"L’État doit-il mettre fin aux injustices ?","function":"Préciser ce que l’État devrait réaliser","reason":"Envisager la justice comme un ordre des fonctions, puis en examiner les limites.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}],"speaker":"Socrate"},{"id":"platon-la-liberte-qui-devient-servitude","code":"P10","author":"Platon","title":"La liberté qui devient servitude","work":"La République","locator":"VIII, 564a","quote":"Une liberté excessive ne peut donc apparemment se muer qu’en une servitude excessive, et cela aussi bien pour l’individu que pour la cité.","notions":["liberte","etat"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une liberté sans aucune limite peut-elle se conserver ?"},{"function":"L’affirmation","sentence":"Socrate soutient que la recherche d’une liberté excessive peut aboutir à une servitude excessive."},{"function":"Les concepts","sentence":"La liberté visée ici est le refus de toute autorité et de toute règle, tandis que la servitude est la soumission à un pouvoir qui ne rencontre plus de limites."},{"function":"La raison","sentence":"Dans l’analyse de Platon, le désordre des désirs et des conflits peut préparer l’appel à un protecteur qui finit par dominer tous les autres."},{"function":"L’exemple","sentence":"Un chef d’abord soutenu contre les puissants peut supprimer ses adversaires puis les garanties de ceux qui l’ont soutenu."},{"function":"La portée","sentence":"La liberté peut donc avoir besoin de limites communes, sans que cela permette de présenter toute démocratie comme une tyrannie en devenir."}],"uses":[{"subject":"L’État est-il le garant de ma liberté ?","function":"Faire apparaître une limite","reason":"L’absence de règle commune peut préparer la domination plutôt que la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"},{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Dépasser une opposition simple","reason":"Certaines contraintes peuvent empêcher la liberté de se détruire elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"}],"speaker":"Socrate"},{"id":"platon-le-silence-de-lecrit","code":"P11","author":"Platon","title":"Le silence de l’écrit","work":"Phèdre","locator":"275d","quote":"Car, à mon avis, ce qu’il y a de terrible, Phèdre, c’est la ressemblance qu’entretient l’écriture avec la peinture.","notions":["langage","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Un texte écrit peut-il expliquer lui-même ce que nous ne comprenons pas en lui ?"},{"function":"L’affirmation","sentence":"Socrate compare l’écriture à la peinture parce que l’une et l’autre semblent vivantes sans pouvoir répondre à nos questions."},{"function":"Les concepts","sentence":"La ressemblance porte sur une présence apparente qui laisse pourtant le lecteur ou le spectateur sans réponse nouvelle."},{"function":"La raison","sentence":"Une fois fixé, le discours répète les mêmes signes et ne choisit ni ses lecteurs ni les explications dont ils ont besoin."},{"function":"L’exemple","sentence":"Une définition écrite ne peut pas reconnaître notre erreur de lecture et la corriger comme le ferait un interlocuteur."},{"function":"La portée","sentence":"L’écrit peut soutenir la compréhension, mais sa conservation ne remplace pas le travail vivant de l’explication."}],"uses":[{"subject":"Le langage n’est-il qu’un outil ?","function":"Examiner une limite du support","reason":"Le discours écrit circule sans pouvoir ajuster sa réponse au lecteur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"Bien parler, est-ce bien penser ?","function":"Introduire l’exigence de justification","reason":"Un discours fixé ne remplace pas l’aptitude vivante à répondre aux objections.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"}],"speaker":"Socrate"},{"id":"platon-linspiration-du-poete","code":"P12","author":"Platon","title":"L’inspiration du poète","work":"Ion","locator":"533e","quote":"En effet, tous les poètes auteurs de vers épiques – je parle des bons poètes – ne sont pas tels par l’effet d’un art, mais c’est inspirés par le dieu et possédés par lui qu’ils profèrent tous ces beaux poèmes.","notions":["art"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment un poète peut-il réussir sans savoir expliquer sa réussite ?"},{"function":"L’affirmation","sentence":"Dans l’Ion, Socrate attribue la puissance des bons poètes à une inspiration divine plutôt qu’à la maîtrise d’un art."},{"function":"Les concepts","sentence":"L’art est ici un savoir réglé dont on peut rendre raison, tandis que l’inspiration fait parler sous l’effet d’une puissance qui nous dépasse."},{"function":"La raison","sentence":"Le dialogue distingue ainsi la force d’une parole poétique et les connaissances que son auteur ou son interprète peut réellement justifier."},{"function":"L’exemple","sentence":"Ion peut émouvoir en récitant Homère sans connaître pour autant la médecine ou la stratégie dont les poèmes parlent."},{"function":"La portée","sentence":"La réussite poétique ne prouve donc pas la possession du savoir correspondant, sans que cela suffise à exclure tout travail du poète."}],"uses":[{"subject":"Faut-il recourir à la notion d’inspiration pour rendre compte de la production artistique ?","function":"Soutenir une hypothèse à discuter","reason":"La beauté produite peut dépasser le savoir explicite de son auteur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’artiste est-il maître de son œuvre ?","function":"Limiter la maîtrise","reason":"Le poète ne commande pas entièrement ce qui fait la valeur de sa production.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=7","sourceLabel":"Recueil académique · p. 7"},{"subject":"L’artiste sait-il ce qu’il fait ?","function":"II.2 : construire la nouvelle réponse","reason":"L’inspiration permet de distinguer produire une œuvre réussie et savoir expliquer sa production.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-l-artiste-sait-il-ce-qu-il-fait.html","a20Step":"II.2","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}],"speaker":"Socrate"},{"id":"platon-le-dialogue-interieur","code":"P13","author":"Platon","title":"Le dialogue intérieur","work":"Théétète","locator":"189e–190a","quote":"Car voici ce que me semble faire l’âme quand elle pense : rien d’autre que dialoguer, s’interrogeant elle-même et répondant, affirmant et niant.","notions":["conscience","langage","raison"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment pouvons-nous discuter une idée lorsque nous sommes seuls ?"},{"function":"L’affirmation","sentence":"Socrate décrit la pensée comme un dialogue que l’âme entretient avec elle-même."},{"function":"Les concepts","sentence":"Dialoguer signifie ici se poser des questions, avancer des réponses et examiner ce que l’on doit affirmer ou nier."},{"function":"La raison","sentence":"La pensée ne reçoit donc pas seulement des idées, elle les confronte avant de se fixer sur un jugement."},{"function":"L’exemple","sentence":"Avant de tenir une promesse pour obligatoire dans une situation nouvelle, nous pouvons en examiner intérieurement les raisons et les objections."},{"function":"La portée","sentence":"La parole intérieure éclaire ainsi le travail du jugement, sans établir que toute forme de pensée soit un discours prononcé en silence."}],"uses":[{"subject":"Penser, est-ce se parler à soi-même ?","function":"Défendre une analyse du penser","reason":"L’interrogation et la réponse peuvent s’effectuer intérieurement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Peut-on penser sans douter ?","function":"Montrer le rôle de l’examen","reason":"Penser implique de mettre des propositions à l’épreuve avant de trancher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"}],"speaker":"Socrate"},{"id":"platon-le-temps-et-leternite","code":"P14","author":"Platon","title":"Le temps et l’éternité","work":"Timée","locator":"37d","quote":"Le démiurge a donc l’idée de fabriquer une image mobile de l’éternité ; et, tandis qu’il met le ciel en ordre, il fabrique de l’éternité qui reste dans l’unité une certaine image éternelle progressant suivant le nombre, celle-là même que précisément nous appelons le « temps ».","notions":["temps"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"Comment un monde changeant peut-il présenter un ordre durable ?"},{"function":"L’affirmation","sentence":"Le Timée présente le temps comme une image mobile de l’éternité produite avec l’organisation du ciel."},{"function":"Les concepts","sentence":"L’éternité demeure dans l’unité, tandis que le temps se déploie dans une succession réglée par le nombre."},{"function":"La raison","sentence":"Les mouvements célestes permettent de retrouver un ordre dans le changement au lieu de le laisser à une succession sans mesure."},{"function":"L’exemple","sentence":"Le retour des jours, des mois et des années donne ainsi des repères réguliers à ce qui naît et se transforme."},{"function":"La portée","sentence":"L’éternité n’est donc pas un temps qui ne finirait jamais, mais ce dont le temps reproduit l’ordre à travers la succession."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer deux modes d’être","reason":"L’éternité ne désigne pas simplement un temps qui durerait sans fin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Maîtrise-t-on le temps ?","function":"Préciser l’objet de la maîtrise","reason":"Le nombre et l’ordre rendent le temps mesurable sans le rendre disponible à volonté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}],"speaker":"Timée"},{"id":"platon-les-richesses-et-la-vertu","code":"P15","author":"Platon","title":"Les richesses et la vertu","work":"Apologie de Socrate","locator":"30b","quote":"Ce n’est pas des richesses que vient la vertu, mais c’est de la vertu que viennent les richesses et tous les autres biens, pour les particuliers comme pour l’État.","notions":["bonheur","devoir"],"edition":"Œuvres complètes, sous la direction de Luc Brisson","publisher":"Flammarion","editionYear":2008,"translator":null,"commentary":[{"function":"Le problème","sentence":"La possession de richesses suffit-elle à rendre une vie bonne ?"},{"function":"L’affirmation","sentence":"Socrate donne la priorité à la vertu plutôt qu’à l’acquisition des richesses."},{"function":"Les concepts","sentence":"La vertu est la qualité morale qui règle notre conduite, tandis que les richesses sont des ressources dont la valeur dépend aussi de l’usage."},{"function":"La raison","sentence":"Une possession peut servir une action bonne ou aggraver une conduite injuste, de sorte que son utilité ne garantit pas son bon emploi."},{"function":"L’exemple","sentence":"Une fortune peut permettre d’aider des proches, mais aussi d’acheter des complicités pour nuire à autrui."},{"function":"La portée","sentence":"Il faut donc prendre soin de sa conduite pour faire bon usage des biens, sans promettre que la vertu enrichira toujours celui qui la pratique."}],"uses":[{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Distinguer possession et bien véritable","reason":"La possession ne suffit pas : il faut examiner le rapport que l’on entretient avec ce que l’on possède.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Définir une condition morale","reason":"Les avantages matériels ne justifient pas le sacrifice de la vertu.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}],"speaker":"Socrate"},{"id":"aristote-le-desir-de-savoir","code":"A01","author":"Aristote","title":"Le désir de savoir","work":"Métaphysique","locator":"A, 1, 980a21","quote":"Tous les humains ont par nature le désir de savoir.","notions":["science","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"La connaissance n’a-t-elle de valeur que lorsqu’elle sert à quelque chose ?"},{"function":"L’affirmation","sentence":"Aristote affirme que le désir de savoir appartient à la nature humaine."},{"function":"Les concepts","sentence":"Ce désir peut porter sur la connaissance elle-même, sans se réduire à la recherche d’un avantage pratique."},{"function":"La raison","sentence":"Aristote en prend pour indice le plaisir des sensations, particulièrement celui de voir, même lorsque nous n’en attendons aucune action utile."},{"function":"L’exemple","sentence":"Nous pouvons ainsi observer les formes d’un paysage par intérêt pour leurs différences, sans vouloir en tirer un produit."},{"function":"La portée","sentence":"La connaissance peut donc valoir pour elle-même, sans que cela rende toute recherche également souhaitable ou prioritaire."}],"uses":[{"subject":"Peut-on désirer savoir pour savoir ?","function":"Soutenir une valeur propre du connaître","reason":"La recherche de connaissance peut être désirée indépendamment de son utilité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Pourquoi désire-t-on savoir ?","function":"Proposer une origine du désir","reason":"Le texte rattache le désir de savoir à la nature humaine et au plaisir de percevoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"La science doit-elle être utile ?","function":"II.1 : introduire une autre exigence","reason":"Le désir de savoir peut donner une valeur propre à la connaissance, distincte de son utilité pratique.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-la-science-doit-elle-etre-utile.html","a20Step":"II.1","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}]},{"id":"aristote-connaitre-la-cause","code":"A02","author":"Aristote","title":"Connaître la cause","work":"Seconds Analytiques","locator":"I, 2, 71b9–12","quote":"Nous pensons connaître scientifiquement chaque chose au sens absolu, et non pas à la manière sophistique par accident, lorsque nous pensons connaître la cause du fait de laquelle la chose est, savoir que c’est bien la cause de la chose et que cette chose ne peut pas être autrement qu’elle n’est.","notions":["science","verite"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Connaître un fait suffit-il pour le comprendre scientifiquement ?"},{"function":"L’affirmation","sentence":"Aristote exige que le savoir scientifique fasse connaître la cause du fait et sa nécessité."},{"function":"Les concepts","sentence":"La cause explique pourquoi la chose est ainsi, tandis que la nécessité signifie qu’elle ne peut pas être autrement dans les conditions considérées."},{"function":"La raison","sentence":"Un constat isolé n’explique pas encore pourquoi le fait se produit et ne donne donc pas à lui seul cette connaissance."},{"function":"L’exemple","sentence":"Voir une éclipse n’équivaut pas à comprendre pourquoi la Terre interposée prive la Lune de lumière."},{"function":"La portée","sentence":"Ce modèle distingue la science du simple constat, mais doit être confronté aux formes de connaissance qui portent sur des faits variables ou probables."}],"uses":[{"subject":"Savoir, est-ce ne rien croire ?","function":"Définir une exigence de connaissance","reason":"La science n’est pas seulement une conviction vraie ; elle doit rendre raison du fait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"},{"subject":"Croire sans savoir, est-ce raisonnable ?","function":"Distinguer assentiment et science","reason":"La croyance peut manquer de l’explication causale requise par le savoir scientifique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}]},{"id":"aristote-apprendre-en-faisant","code":"A03","author":"Aristote","title":"Apprendre en faisant","work":"Éthique à Nicomaque","locator":"II, 1, 1103a32–33","quote":"En effet, ce qu’on doit apprendre à faire, c’est en le faisant que nous l’apprenons.","notions":["technique","art"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Comment acquérir une capacité que l’on ne sait pas encore exercer ?"},{"function":"L’affirmation","sentence":"Aristote affirme que certaines activités s’apprennent par leur pratique."},{"function":"Les concepts","sentence":"Apprendre à faire consiste à former une capacité durable, et pas seulement à recevoir une règle."},{"function":"La raison","sentence":"L’exercice transforme progressivement celui qui agit et lui permet de mieux accomplir ce qu’il essaie déjà de faire."},{"function":"L’exemple","sentence":"On apprend à jouer d’un instrument en jouant, en corrigeant ses erreurs et en reprenant les passages difficiles."},{"function":"La portée","sentence":"La pratique est donc formatrice, à condition de ne pas confondre un exercice qui progresse avec la répétition aveugle d’un défaut."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Construire la part de vérité de la pratique","reason":"L’exercice forme des capacités, sans suffire à expliquer toute création.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Installer un acquis à dépasser","reason":"La pratique est nécessaire à une maîtrise, mais ne définit pas seule l’artiste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-devenir-juste","code":"A04","author":"Aristote","title":"Devenir juste","work":"Éthique à Nicomaque","locator":"II, 1, 1103b1–2","quote":"De la même façon, c’est donc aussi en exécutant des actes justes que nous devenons justes, des actes tempérants qu’on devient tempérant et des actes courageux qu’on devient courageux.","notions":["devoir","justice"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Suffit-il de connaître la justice pour devenir juste ?"},{"function":"L’affirmation","sentence":"Aristote affirme que les qualités morales se forment par l’accomplissement des actes correspondants."},{"function":"Les concepts","sentence":"Devenir juste signifie acquérir une disposition stable à choisir et à faire ce qui est juste."},{"function":"La raison","sentence":"Nos actes répétés façonnent nos manières de désirer, de décider et de réagir, comme les exercices façonnent une capacité technique."},{"function":"L’exemple","sentence":"Apprendre à partager équitablement prépare à reconnaître et à choisir l’équité dans des situations nouvelles."},{"function":"La portée","sentence":"La formation morale demande donc des actes, mais une action extérieurement juste ne prouve pas encore que son auteur agisse avec justice et pour de bonnes raisons."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Compléter la connaissance par la formation","reason":"Connaître le bien ne remplace pas l’acquisition d’une disposition à l’accomplir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Le sentiment de la justice est-il naturel ?","function":"Construire la part de l’acquisition","reason":"La conduite juste suppose une formation par les actes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"aristote-le-juste-milieu","code":"A05","author":"Aristote","title":"Le juste milieu","work":"Éthique à Nicomaque","locator":"II, 6, 1106b36–1107a1","quote":"Par conséquent, la vertu est un état décisionnel qui consiste en une moyenne, fixée relativement à nous.","notions":["devoir","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Agir bien consiste-t-il à appliquer partout une quantité identique ?"},{"function":"L’affirmation","sentence":"Aristote définit la vertu comme une disposition à choisir un milieu relatif à celui qui agit."},{"function":"Les concepts","sentence":"Ce milieu évite l’excès et le défaut selon les circonstances, au lieu de partager mécaniquement la distance entre deux extrêmes."},{"function":"La raison","sentence":"Une action réussie doit convenir à la situation et à la personne, ce qui exige un jugement plutôt qu’une recette."},{"function":"L’exemple","sentence":"Le courage évite ainsi la fuite devant tout danger comme l’exposition irréfléchie à n’importe quel risque."},{"function":"La portée","sentence":"La vertu recherche donc ce qui convient, sans signifier que toute action mauvaise pourrait devenir bonne par simple modération."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Préciser le jugement pratique","reason":"La règle doit être appliquée par un choix attentif aux circonstances.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Construire une transformation du désir","reason":"La vertu éduque les affections au lieu de seulement les supprimer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"aristote-deliberer-sur-les-moyens","code":"A06","author":"Aristote","title":"Délibérer sur les moyens","work":"Éthique à Nicomaque","locator":"III, 3, 1112b11–12","quote":"D’autre part, nous ne délibérons pas des fins, mais des moyens pour y parvenir.","notions":["technique","raison"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Que cherchons-nous lorsque nous délibérons sur une action ?"},{"function":"L’affirmation","sentence":"Aristote distingue la fin déjà posée et les moyens que la délibération examine pour l’atteindre."},{"function":"Les concepts","sentence":"La fin est ce que nous voulons obtenir, tandis que les moyens sont les actions susceptibles d’y conduire."},{"function":"La raison","sentence":"Une fois le but fixé, la délibération porte sur ce qui dépend de nous et sur les voies réellement possibles."},{"function":"L’exemple","sentence":"Le médecin qui cherche à guérir compare les traitements adaptés plutôt que de redéfinir la guérison à chaque décision."},{"function":"La portée","sentence":"Choisir des moyens efficaces ne suffit donc pas à justifier une fin, dont la valeur peut demander un autre examen."}],"uses":[{"subject":"Existe-t-il des techniques pour être heureux ?","function":"Distinguer fin et moyens","reason":"Un procédé peut aider à atteindre un but sans établir en quoi consiste le bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Délimiter la technique","reason":"Savoir exécuter les moyens ne règle pas à soi seul la valeur de la fin artistique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-les-amis-et-les-autres-biens","code":"A07","author":"Aristote","title":"Les amis et les autres biens","work":"Éthique à Nicomaque","locator":"VIII, 1, 1155a5–6","quote":"Sans amis en effet nul ne choisirait de vivre, aurait-il tous les biens qui restent ; car c’est lorsqu’ils sont riches et en possession des formes du pouvoir et de la puissance que les gens éprouvent surtout le besoin d’amis.","notions":["bonheur"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Posséder tous les autres biens rendrait-il l’amitié superflue ?"},{"function":"L’affirmation","sentence":"Aristote affirme que même une vie comblée de richesses et de pouvoir resterait indésirable sans amis."},{"function":"Les concepts","sentence":"L’amitié est une relation dans laquelle on souhaite du bien à l’autre pour lui-même et de manière réciproque."},{"function":"La raison","sentence":"Les biens possédés ne remplacent ni la possibilité de les partager ni celle d’agir avec des personnes auxquelles on tient."},{"function":"L’exemple","sentence":"Une réussite matérielle peut laisser sans personne avec qui se réjouir ou accomplir une action généreuse."},{"function":"La portée","sentence":"L’amitié appartient donc à la vie bonne au lieu de seulement compenser un manque de ressources."}],"uses":[{"subject":"La recherche du bonheur est-elle un idéal égoïste ?","function":"Contester l’autosuffisance solitaire","reason":"La vie bonne inclut un lien avec autrui qui ne se réduit pas à sa possession.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Suffit-il d’avoir ce que l’on désire pour être heureux ?","function":"Limiter l’accumulation des biens","reason":"La possession de nombreux biens peut laisser manquer l’amitié.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"aristote-le-bonheur-et-le-loisir","code":"A08","author":"Aristote","title":"Le bonheur et le loisir","work":"Éthique à Nicomaque","locator":"X, 7, 1177b4","quote":"De plus, le bonheur semble impliquer le loisir.","notions":["bonheur","travail"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Être libéré du travail suffit-il pour être heureux ?"},{"function":"L’affirmation","sentence":"Aristote rapporte le bonheur au loisir, c’est-à-dire à une activité choisie pour elle-même."},{"function":"Les concepts","sentence":"Le loisir s’oppose ici à l’occupation imposée par la nécessité, et non à toute activité."},{"function":"La raison","sentence":"Si l’on peine pour obtenir du repos, ce repos doit permettre une manière de vivre qui ait sa valeur propre."},{"function":"L’exemple","sentence":"Étudier une question pour la comprendre peut ainsi donner un sens au temps libéré, au lieu de seulement remplir un vide."},{"function":"La portée","sentence":"Le bonheur ne se réduit donc ni à travailler sans fin ni à ne rien faire, mais demande d’examiner les activités auxquelles la vie peut se consacrer."}],"uses":[{"subject":"Travailler moins, est-ce vivre mieux ?","function":"Distinguer temps libéré et vie bonne","reason":"La réduction de la peine vaut par les activités qu’elle rend possibles.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"},{"subject":"Faut-il travailler pour être heureux ?","function":"Distinguer condition et fin","reason":"Le travail peut préparer les conditions d’une vie qui trouve sa fin ailleurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=68","sourceLabel":"Recueil académique · p. 68"}]},{"id":"aristote-lanimal-politique","code":"A09","author":"Aristote","title":"L’animal politique","work":"Les Politiques","locator":"I, 2, 1253a7–8","quote":"Que l’homme soit un animal politique plus que n’importe quelle abeille et que n’importe quel animal grégaire, c’est évident.","notions":["etat","langage"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Pierre Pellegrin (remarque préliminaire, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"La vie politique n’est-elle qu’une façon de se regrouper ?"},{"function":"L’affirmation","sentence":"Aristote affirme que l’être humain est politique dans un sens plus fort que les animaux vivant en groupe."},{"function":"Les concepts","sentence":"La vie politique suppose une communauté capable de discuter ce qui est avantageux, juste ou injuste."},{"function":"La raison","sentence":"Le langage permet de mettre ces évaluations en commun, au-delà de la simple expression du plaisir ou de la douleur."},{"function":"L’exemple","sentence":"Débattre d’une loi commune demande ainsi de donner des raisons sur ce qui doit valoir pour les citoyens."},{"function":"La portée","sentence":"La communauté humaine ne se comprend donc pas seulement par la proximité physique ou l’instinct de regroupement."}],"uses":[{"subject":"Doit-on tout attendre de l’État ?","function":"Fonder le besoin de communauté","reason":"La communauté politique répond à une dimension constitutive de la vie humaine, sans se confondre avec toute sa vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=25","sourceLabel":"Recueil académique · p. 25"},{"subject":"Le langage des animaux est-il comparable à celui des hommes ?","function":"Introduire une différence de fonction","reason":"L’enjeu politique du langage distingue la communauté humaine du simple grégarisme.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"}]},{"id":"aristote-le-langage-et-le-juste","code":"A10","author":"Aristote","title":"Le langage et le juste","work":"Les Politiques","locator":"I, 2, 1253a14–15","quote":"Mais le langage existe en vue de manifester l’avantageux et le nuisible, et par suite aussi le juste et l’injuste.","notions":["langage","justice","etat"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Pierre Pellegrin (remarque préliminaire, PDF p. 18)","commentary":[{"function":"Le problème","sentence":"Le langage sert-il seulement à transmettre des sensations ou des informations ?"},{"function":"L’affirmation","sentence":"Aristote lui attribue la capacité de rendre manifestes l’utile, le nuisible, le juste et l’injuste."},{"function":"Les concepts","sentence":"Manifester signifie rendre une évaluation compréhensible et discutable par d’autres personnes."},{"function":"La raison","sentence":"La mise en commun de tels jugements permet aux hommes de former une communauté qui se donne des règles."},{"function":"L’exemple","sentence":"Discuter de la répartition d’une charge publique exige d’expliquer pourquoi une solution serait équitable et pas seulement avantageuse pour soi."},{"function":"La portée","sentence":"Le langage contribue donc à la vie politique, sans garantir que les décisions prises par la parole soient toujours justes."}],"uses":[{"subject":"Faire usage du langage, est-ce renoncer à la violence ?","function":"Construire une alternative à la force","reason":"Discuter publiquement du juste peut remplacer la seule imposition d’un intérêt.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Le langage n’est-il qu’un outil ?","function":"Élargir la fonction du langage","reason":"Le langage participe à la constitution de la communauté politique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-imiter-pour-apprendre","code":"A11","author":"Aristote","title":"Imiter pour apprendre","work":"Poétique","locator":"4, 1448b4–8","quote":"En effet, les êtres humains sont dès leur enfance naturellement enclins à imiter, et cela précisément les distingue des autres animaux : l’homme est l’être le plus enclin à imiter, et il fait ses premiers apprentissages au moyen de l’imitation.","notions":["art","nature"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"L’imitation empêche-t-elle de comprendre et d’apprendre ?"},{"function":"L’affirmation","sentence":"Aristote voit dans l’imitation une tendance humaine naturelle et une origine des premiers apprentissages."},{"function":"Les concepts","sentence":"Imiter consiste à reprendre ou à représenter une action ou une forme, ce qui n’exclut pas d’en comprendre l’organisation."},{"function":"La raison","sentence":"L’enfant apprend en reproduisant des gestes, et le plaisir de reconnaître ce qui est représenté contribue aussi à l’intérêt des œuvres."},{"function":"L’exemple","sentence":"Un dessin peut nous faire reconnaître la posture d’un animal en sélectionnant quelques traits au lieu de tout copier."},{"function":"La portée","sentence":"L’imitation peut donc former la perception et l’intelligence, sans suffire à expliquer à elle seule toute création artistique."}],"uses":[{"subject":"Est-ce en imitant qu’on devient artiste ?","function":"Installer le rôle de l’imitation","reason":"L’imitation forme les premières capacités et ne s’oppose pas d’emblée à l’art.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il prendre la nature pour modèle ?","function":"Nuancer l’opposition nature et culture","reason":"L’imitation peut être naturelle à l’être humain sans fixer un modèle unique à reproduire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"aristote-la-connaissance-par-la-fiction","code":"A12","author":"Aristote","title":"La connaissance par la fiction","work":"Poétique","locator":"9, 1451b6–7","quote":"En effet, la poésie raconte les événements davantage dans leur généralité ; l’histoire, les événements dans leur particularité.","notions":["art","verite"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Une fiction peut-elle nous apprendre quelque chose sans raconter un fait réel ?"},{"function":"L’affirmation","sentence":"Aristote distingue le récit des faits particuliers et la représentation de ce qui pourrait arriver de manière générale."},{"function":"Les concepts","sentence":"Le général désigne ici des rapports vraisemblables ou nécessaires entre un type de situation, une conduite et ses conséquences."},{"function":"La raison","sentence":"Une intrigue inventée peut faire comprendre ces rapports en les organisant de manière cohérente."},{"function":"L’exemple","sentence":"Une tragédie peut montrer comment une décision aveugle conduit au malheur sans que tous ses personnages aient réellement existé."},{"function":"La portée","sentence":"La connaissance apportée par une œuvre ne se mesure donc pas seulement à l’exactitude historique des événements qu’elle représente."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","function":"Établir un pouvoir de compréhension","reason":"La fiction fait saisir des rapports vraisemblables ou nécessaires entre les actions.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il indifférent à la vérité ?","function":"Distinguer vérité et fait réel","reason":"Ne pas raconter un événement réellement arrivé n’implique pas de ne rien faire comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"}]},{"id":"aristote-la-main-et-lintelligence","code":"A13","author":"Aristote","title":"La main et l’intelligence","work":"Les Parties des animaux","locator":"IV, 10, 687a7–10","quote":"Anaxagore dit ainsi que c’est du fait qu’il a des mains que l’être humain est le plus intelligent des animaux, alors qu’il est rationnel que ce soit du fait qu’il est le plus intelligent qu’il soit pourvu de mains.","notions":["technique","nature"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"L’intelligence vient-elle de l’outil ou explique-t-elle la capacité d’en user ?"},{"function":"L’affirmation","sentence":"Aristote refuse la thèse d’Anaxagore qui fait des mains la cause de la supériorité intellectuelle humaine."},{"function":"Les concepts","sentence":"Il distingue la possession d’un instrument et l’aptitude à l’employer de plusieurs manières."},{"function":"La raison","sentence":"Dans son explication, la nature attribue la main à l’être capable de tirer parti de nombreux instruments."},{"function":"L’exemple","sentence":"Posséder une flûte ne donne pas l’art d’en jouer, alors que cet art permet de faire bon usage de l’instrument."},{"function":"La portée","sentence":"La technique suppose donc des capacités d’usage, mais cette explication ne suffit pas à nier que les outils puissent ensuite développer ces capacités."}],"uses":[{"subject":"Y a-t-il de l’intelligence dans les techniques ?","function":"Articuler capacité et instrument","reason":"La main polyvalente rend possible l’exercice de nombreuses techniques, selon une intelligence qui sait en user.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=99","sourceLabel":"Recueil académique · p. 99"},{"subject":"La maîtrise technique suffit-elle à définir l’artiste ?","function":"Distinguer instrument et aptitude","reason":"La disponibilité de l’instrument ne produit pas à elle seule la capacité d’en user.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=61","sourceLabel":"Recueil académique · p. 61"}]},{"id":"aristote-le-temps-et-le-mouvement","code":"A14","author":"Aristote","title":"Le temps et le mouvement","work":"Physique","locator":"IV, 11, 219b1–2","quote":"Car c’est cela le temps : le nombre d’un mouvement selon l’antérieur et le postérieur.","notions":["temps"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":null,"commentary":[{"function":"Le problème","sentence":"Le temps se confond-il avec les changements que nous observons ?"},{"function":"L’affirmation","sentence":"Aristote définit le temps comme ce qui permet de nombrer le mouvement selon l’avant et l’après."},{"function":"Les concepts","sentence":"Le nombre désigne ici l’ordre et la quantité du changement, tandis que l’antérieur et le postérieur distinguent ses moments."},{"function":"La raison","sentence":"Nous reconnaissons un intervalle de temps lorsque nous distinguons des étapes d’un changement et ce qui les sépare."},{"function":"L’exemple","sentence":"Le déplacement régulier d’une aiguille permet de mesurer l’attente d’un événement sans être cet événement lui-même."},{"function":"La portée","sentence":"Le temps se rapporte donc au mouvement sans lui être identique, et sa mesure ne donne pas le pouvoir d’en commander le passage."}],"uses":[{"subject":"Maîtrise-t-on le temps ?","function":"Distinguer mesure et pouvoir","reason":"Mesurer un mouvement ne signifie pas commander son écoulement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"},{"subject":"Est-il possible d’échapper au temps ?","function":"Préciser la condition du devenir","reason":"Interroger le rapport entre être soumis au changement et être dans le temps.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"aristote-des-rigueurs-differentes","code":"A15","author":"Aristote","title":"Des rigueurs différentes","work":"Éthique à Nicomaque","locator":"I, 7, 1098a26–29","quote":"Il faut cependant garder aussi en mémoire ce qu’on a dit précédemment, et ne pas réclamer le même genre de rigueur partout.","notions":["raison","science","devoir"],"edition":"Œuvres complètes, sous la direction de Pierre Pellegrin","publisher":"Flammarion","editionYear":2014,"translator":"Richard Bodéüs (identifié dans la note sur cette édition, PDF p. 19)","commentary":[{"function":"Le problème","sentence":"Toute connaissance doit-elle atteindre la précision d’une démonstration mathématique ?"},{"function":"L’affirmation","sentence":"Aristote demande d’ajuster le genre de rigueur à l’objet étudié."},{"function":"Les concepts","sentence":"La rigueur consiste à justifier suffisamment ce que l’on affirme selon la nature du problème."},{"function":"La raison","sentence":"Une matière variable ne permet pas toujours la même exactitude qu’un objet défini par des rapports nécessaires."},{"function":"L’exemple","sentence":"Le géomètre cherche les propriétés de l’angle droit, tandis que le menuisier en cherche une réalisation assez précise pour son travail."},{"function":"La portée","sentence":"Exiger une précision adaptée ne dispense donc pas d’argumenter, mais évite de rendre impossible un jugement en lui demandant une certitude étrangère à son objet."}],"uses":[{"subject":"Faut-il suivre sa raison pour agir moralement ?","function":"Distinguer raison pratique et démonstration","reason":"L’incertitude des situations ne supprime pas l’exigence de jugement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=50","sourceLabel":"Recueil académique · p. 50"},{"subject":"Comment savoir ce qui est juste ?","function":"Délimiter le type de certitude attendu","reason":"La recherche du juste ne se traite pas nécessairement comme un calcul géométrique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=30","sourceLabel":"Recueil académique · p. 30"}]},{"id":"nietzsche-la-meconnaissance-de-soi","code":"N01","author":"Nietzsche","title":"La méconnaissance de soi","work":"Généalogie de la morale","locator":"Avant-propos, § 1","quote":"Nous ne nous connaissons pas nous-mêmes, nous les hommes de la connaissance, et nous sommes nous-mêmes inconnus à nous-mêmes.","notions":["conscience","inconscient"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel, Ole Hansen-Løve, Théo Leydenbach et Pierre Pénisson","commentary":[{"function":"Le problème","sentence":"La connaissance du monde garantit-elle la connaissance de soi ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que les hommes voués à la connaissance peuvent demeurer étrangers à eux-mêmes."},{"function":"Les concepts","sentence":"Se connaître demande de comprendre ses propres manières de vivre et de vouloir, au-delà du savoir que l’on accumule sur des objets."},{"function":"La raison","sentence":"L’attention portée à ce que nous cherchons peut nous détourner de l’examen de celui qui cherche."},{"function":"L’exemple","sentence":"Un chercheur peut décrire avec précision son domaine sans reconnaître ce qui oriente son ambition ou ses rivalités."},{"function":"La portée","sentence":"La proximité avec soi ne vaut donc pas connaissance immédiate, sans que cela rende tout examen de soi impossible."}],"uses":[{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Contester un privilège immédiat","reason":"La proximité avec soi peut aller de pair avec la méconnaissance de ses propres activités.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Être conscient, est-ce savoir ?","function":"Distinguer expérience de soi et connaissance","reason":"Se vivre soi-même ne suffit pas à se comprendre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"nietzsche-les-interpretations-morales","code":"N02","author":"Nietzsche","title":"Les interprétations morales","work":"Par-delà bien et mal","locator":"§ 108","quote":"Il n’y a pas de phénomènes moraux du tout, mais seulement une interprétation morale de phénomènes…","notions":["devoir","justice"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Le bien et le mal sont-ils des propriétés que l’on constaterait directement dans les faits ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que la qualification morale d’un phénomène relève d’une interprétation."},{"function":"Les concepts","sentence":"Interpréter moralement consiste à rapporter ce qui arrive à des valeurs qui permettent de le louer ou de le condamner."},{"function":"La raison","sentence":"La description d’un geste ne contient pas encore les critères au nom desquels nous le jugeons."},{"function":"L’exemple","sentence":"Garder le silence peut être loué comme de la discrétion ou condamné comme de la lâcheté selon le sens qu’on lui donne."},{"function":"La portée","sentence":"Il faut donc examiner les évaluations à l’œuvre dans un jugement moral, sans conclure que toutes les interprétations ont la même valeur."}],"uses":[{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Mettre en cause l’évidence morale","reason":"Une évaluation intériorisée ne prouve pas sa propre validité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"},{"subject":"Le sentiment de la justice est-il naturel ?","function":"Introduire l’histoire de l’évaluation","reason":"Ce qui paraît immédiatement juste peut résulter d’une interprétation acquise.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=46","sourceLabel":"Recueil académique · p. 46"}]},{"id":"nietzsche-devenir-ce-que-lon-combat","code":"N03","author":"Nietzsche","title":"Devenir ce que l’on combat","work":"Par-delà bien et mal","locator":"§ 146","quote":"Que celui qui lutte avec des monstres veille à ce que cela ne le transforme pas en monstre.","notions":["justice","etat"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Une lutte juste protège-t-elle toujours celui qui la mène de devenir injuste ?"},{"function":"L’affirmation","sentence":"Nietzsche avertit que le combat contre les monstres peut transformer le combattant en monstre."},{"function":"Les concepts","sentence":"Le monstre désigne ici ce dont on combat la violence ou la cruauté, et la transformation touche les pratiques de celui qui s’y oppose."},{"function":"La raison","sentence":"L’habitude d’affronter un adversaire peut faire adopter ses moyens et perdre de vue la fin initiale."},{"function":"L’exemple","sentence":"Un pouvoir qui prétend combattre la terreur peut en venir à imposer lui-même la peur et l’arbitraire."},{"function":"La portée","sentence":"La valeur d’un combat ne dispense donc pas d’examiner ses moyens et leurs effets sur ceux qui les emploient."}],"uses":[{"subject":"Le malheur donne-t-il le droit d’être injuste ?","function":"Limiter les moyens de la riposte","reason":"Combattre un mal ne légitime pas la reproduction de ce mal.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"L’État doit-il préférer l’injustice au désordre ?","function":"Mettre à l’épreuve une justification","reason":"Lutter contre le désordre peut corrompre la fin annoncée si les moyens deviennent injustes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"}]},{"id":"nietzsche-les-affects-qui-se-combattent","code":"N04","author":"Nietzsche","title":"Les affects qui se combattent","work":"Par-delà bien et mal","locator":"§ 117","quote":"La volonté de surmonter un affect n’est en dernière instance que la volonté d’un autre ou de plusieurs autres affects.","notions":["conscience","inconscient","liberte"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Lorsque nous maîtrisons un désir, est-ce nécessairement la raison seule qui commande ?"},{"function":"L’affirmation","sentence":"Nietzsche propose de comprendre la domination d’un affect par la force d’autres affects."},{"function":"Les concepts","sentence":"Un affect est une manière de sentir et d’être poussé à agir, comme la peur, la fierté ou l’attachement."},{"function":"La raison","sentence":"La décision de résister peut donc être soutenue par des forces affectives que l’on ne reconnaît pas immédiatement."},{"function":"L’exemple","sentence":"Refuser une satisfaction présente peut tenir au désir plus fort de réussir, de tenir une promesse ou de garder l’estime d’autrui."},{"function":"La portée","sentence":"La maîtrise de soi demande ainsi de comprendre l’organisation de nos désirs, au lieu de supposer une volonté sans aucun mobile affectif."}],"uses":[{"subject":"Pouvons-nous faire coïncider nos désirs avec nos devoirs ?","function":"Déplacer l’opposition raison et désir","reason":"Une conduite réglée peut mobiliser et organiser des affects.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"},{"subject":"Sommes-nous conscients de ce que nous désirons ?","function":"Interroger le motif de la maîtrise","reason":"Le désir de se maîtriser peut lui-même avoir des mobiles affectifs inaperçus.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"nietzsche-le-ressentiment-et-les-valeurs","code":"N05","author":"Nietzsche","title":"Le ressentiment et les valeurs","work":"Généalogie de la morale","locator":"I, § 10","quote":"L’insurrection des esclaves dans la morale commence lorsque le ressentiment lui-même devient créateur et engendre des valeurs : le ressentiment d’êtres tels que la véritable réaction, celle de l’acte, leur est interdite, qui ne s’en sortent indemnes que par une vengeance imaginaire.","notions":["devoir","justice"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel, Ole Hansen-Løve, Théo Leydenbach et Pierre Pénisson","commentary":[{"function":"Le problème","sentence":"Des valeurs morales peuvent-elles naître d’une impossibilité d’agir ?"},{"function":"L’affirmation","sentence":"Nietzsche décrit le ressentiment comme une force capable de créer des valeurs."},{"function":"Les concepts","sentence":"Le ressentiment est une hostilité durable qui, ne pouvant se décharger dans l’action, se transforme en évaluation de l’adversaire."},{"function":"La raison","sentence":"La vengeance devient alors imaginaire, car elle déprécie ce qu’elle ne peut effectivement vaincre."},{"function":"L’exemple","sentence":"Une personne impuissante à rivaliser peut présenter toute réussite adverse comme un vice et sa propre impuissance comme une vertu."},{"function":"La portée","sentence":"Cette analyse invite à interroger l’origine des jugements, sans autoriser à réduire toute demande de justice à du ressentiment."}],"uses":[{"subject":"Ressentir l’injustice m’apprend-il ce qui est juste ?","function":"Distinguer ressentiment et jugement juste","reason":"Un sentiment d’impuissance peut produire une évaluation sans en garantir la justice.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=31","sourceLabel":"Recueil académique · p. 31"},{"subject":"Suffit-il d’avoir bonne conscience pour être sûr d’agir moralement ?","function":"Interroger la provenance des valeurs","reason":"L’origine affective d’un jugement peut rester masquée à celui qui le porte.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=22","sourceLabel":"Recueil académique · p. 22"}]},{"id":"nietzsche-les-convictions-comme-prisons","code":"N06","author":"Nietzsche","title":"Les convictions comme prisons","work":"L’Antéchrist","locator":"§ 54","quote":"Les convictions sont des prisons.","notions":["liberte","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Éric Blondel","commentary":[{"function":"Le problème","sentence":"Une conviction peut-elle empêcher de penser librement ?"},{"function":"L’affirmation","sentence":"Nietzsche compare les convictions à des prisons lorsqu’elles soumettent le jugement au lieu de le servir."},{"function":"Les concepts","sentence":"La conviction devient enfermement quand une idée est tenue pour intouchable et décide d’avance de ce que l’on acceptera d’examiner."},{"function":"La raison","sentence":"Celui qui en dépend écarte les objections pour préserver sa certitude au lieu de mesurer celle-ci aux objections."},{"function":"L’exemple","sentence":"Une personne persuadée qu’un groupe a toujours tort peut refuser d’entendre même les raisons qu’il avance."},{"function":"La portée","sentence":"La liberté de penser exige donc de pouvoir reprendre ses convictions, sans imposer l’indécision permanente ni l’absence de toute fin."}],"uses":[{"subject":"Croire nous empêche-t-il de chercher la vérité ?","function":"Soutenir une objection au dogmatisme","reason":"Tenir une affirmation pour intouchable ferme l’enquête.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Montrer une servitude intérieure","reason":"L’enfermement peut venir d’une conviction à laquelle on ne s’autorise plus à toucher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"nietzsche-lhypothese-scientifique","code":"N07","author":"Nietzsche","title":"L’hypothèse scientifique","work":"Le Gai Savoir","locator":"§ 344","quote":"Dans la science, les convictions n’ont pas droit de cité, voilà ce que l’on dit à juste titre : c’est seulement lorsqu’elles s’abaissent au rang modeste d’une hypothèse, d’un point de vue expérimental provisoire, d’une fiction régulatrice, que l’on a le droit de leur accorder l’accès au royaume de la connaissance et de leur y reconnaître même une certaine valeur, – toujours avec cette restriction de demeurer soumises à la surveillance policière, à la police de la méfiance.","notions":["science","verite","religion"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Quelle différence sépare une hypothèse scientifique d’une conviction intangible ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme qu’une proposition n’entre dans la science qu’en acceptant d’être tenue pour provisoire et examinable."},{"function":"Les concepts","sentence":"L’hypothèse est une explication proposée à l’épreuve, tandis que la conviction prétend ici soustraire son contenu à la remise en question."},{"function":"La raison","sentence":"La discipline scientifique exige que les raisons de conserver une proposition puissent être discutées et ses insuffisances recherchées."},{"function":"L’exemple","sentence":"Une explication que des observations contraires ne permettraient jamais de corriger serait protégée de l’examen plutôt que soutenue par lui."},{"function":"La portée","sentence":"Le passage distingue ainsi recherche et dogmatisme, avant d’interroger dans la suite du paragraphe la confiance des savants dans la valeur de la vérité."}],"uses":[{"subject":"Croire en la science, est-ce une forme de religion ?","function":"Distinguer méthode et adhésion inconditionnelle","reason":"L’hypothèse scientifique doit rester exposée à la critique.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=56","sourceLabel":"Recueil académique · p. 56"},{"subject":"Savoir, est-ce ne rien croire ?","function":"Nuancer l’opposition","reason":"Une hypothèse est admise provisoirement sans être tenue pour une certitude intangible.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}]},{"id":"nietzsche-lart-et-la-lucidite","code":"N08","author":"Nietzsche","title":"L’art et la lucidité","work":"Le Gai Savoir","locator":"§ 107","quote":"Si nous n’avions pas donné notre approbation aux arts et inventé cette espèce de culte du non-vrai : la compréhension de l’universalité du non-vrai et du mensonge que nous offrent à présent les sciences – la compréhension de l’illusion et de l’erreur comme condition de l’existence connaissante et percevante –, nous seraient totalement insupportables.","notions":["art","verite","bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Comment supporter une connaissance qui révèle la part d’illusion dans notre existence ?"},{"function":"L’affirmation","sentence":"Nietzsche attribue à l’art la puissance de rendre cette lucidité vivable."},{"function":"Les concepts","sentence":"L’apparence artistique est une forme que nous savons produite et à laquelle nous pouvons pourtant prendre plaisir."},{"function":"La raison","sentence":"Elle permet de ne pas réduire toute expérience à la seule dénonciation de ses erreurs ou de ses imperfections."},{"function":"L’exemple","sentence":"Une œuvre peut donner forme à une souffrance sans la supprimer ni prétendre qu’elle n’a jamais eu lieu."},{"function":"La portée","sentence":"L’art peut donc soutenir une relation à la vérité, sans se confondre avec un mensonge destiné à tromper autrui."}],"uses":[{"subject":"L’art nous aide-t-il à vivre ?","function":"Défendre une nécessité de l’art","reason":"L’expérience esthétique permet une relation supportable à l’existence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Faire apparaître un coût de la lucidité","reason":"La connaissance peut demander une puissance de mise en forme pour être vécue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"}]},{"id":"nietzsche-donner-forme-a-son-caractere","code":"N09","author":"Nietzsche","title":"Donner forme à son caractère","work":"Le Gai Savoir","locator":"§ 290","quote":"« Donner du style » à son caractère – un art grand et rare !","notions":["conscience","liberte"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Patrick Wotling","commentary":[{"function":"Le problème","sentence":"Devenir soi-même consiste-t-il seulement à découvrir un caractère déjà fixé ?"},{"function":"L’affirmation","sentence":"Nietzsche présente la mise en forme de son caractère comme un art exigeant."},{"function":"Les concepts","sentence":"Donner du style signifie organiser ses forces et ses faiblesses selon une forme que l’on travaille."},{"function":"La raison","sentence":"Ce travail suppose de reconnaître ses dispositions puis de les exercer, de les transformer ou de leur donner une autre place."},{"function":"L’exemple","sentence":"Une grande sensibilité peut devenir un obstacle si elle nous disperse ou une ressource si un travail d’écriture lui donne une forme."},{"function":"La portée","sentence":"La formation de soi unit donc connaissance et exercice, sans permettre de se fabriquer arbitrairement à partir de rien."}],"uses":[{"subject":"Faut-il apprendre à se connaître soi-même ?","function":"Relier connaissance et formation de soi","reason":"Reconnaître ses forces et ses faiblesses peut permettre de les organiser.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=129","sourceLabel":"Recueil académique · p. 129"},{"subject":"Suis-je le mieux placé pour me connaître ?","function":"Déplacer la connaissance vers une tâche","reason":"Se connaître demande un travail de composition plutôt qu’une simple inspection immédiate.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"nietzsche-se-liberer-et-creer","code":"N10","author":"Nietzsche","title":"Se libérer et créer","work":"Ainsi parlait Zarathoustra","locator":"I, « Des trois métamorphoses »","quote":"Créer des valeurs nouvelles, le lion lui-même n’y est pas encore apte ; mais s’affranchir afin de devenir apte à créer des valeurs nouvelles, voilà ce que peut la force du lion.","notions":["liberte","devoir"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Geneviève Bianquis, traduction revue par Paul Mathias","commentary":[{"function":"Le problème","sentence":"Suffit-il de refuser les valeurs reçues pour devenir capable de créer ?"},{"function":"L’affirmation","sentence":"Zarathoustra distingue la libération accomplie par le lion et la création de valeurs nouvelles."},{"function":"Les concepts","sentence":"Le lion représente la force de dire non à une autorité qui impose ses commandements comme sacrés."},{"function":"La raison","sentence":"Ce refus ouvre une liberté, mais ne fournit pas encore les fins auxquelles elle pourra se consacrer."},{"function":"L’exemple","sentence":"Abandonner une règle imposée ne dit pas encore quel engagement nous voulons prendre ni quelle vie nous voulons construire."},{"function":"La portée","sentence":"La liberté ne s’achève donc pas dans l’opposition, puisque l’affirmation de nouvelles valeurs demande une autre puissance, représentée ensuite par l’enfant."}],"uses":[{"subject":"Peut-on opposer le devoir à la liberté ?","function":"Distinguer refus et création","reason":"Dire non à une obligation peut être une étape sans constituer l’autonomie entière.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=40","sourceLabel":"Recueil académique · p. 40"},{"subject":"Puis-je perdre ma liberté de penser ?","function":"Construire une émancipation","reason":"La critique des valeurs reçues ouvre une possibilité, sans fournir à elle seule de nouvelles valeurs.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"}]},{"id":"nietzsche-les-limites-de-la-connaissance","code":"N11","author":"Nietzsche","title":"Les limites de la connaissance","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 5","quote":"La sagesse trace des limites, même à la connaissance.","notions":["raison","bonheur","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Faut-il vouloir tout connaître sans jamais interroger ce que cette recherche engage ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme que la sagesse peut fixer des limites au désir de connaissance."},{"function":"Les concepts","sentence":"La sagesse désigne ici une manière de conduire sa vie qui ne traite pas tout savoir comme un bien inconditionnel."},{"function":"La raison","sentence":"La recherche doit aussi répondre de ce qu’elle exige de nous et de la place qu’elle prend parmi nos activités."},{"function":"L’exemple","sentence":"Chercher sans fin à connaître chaque jugement d’autrui sur nous peut nourrir l’inquiétude au lieu d’éclairer une décision."},{"function":"La portée","sentence":"Interroger les limites du connaître ne revient donc pas à préférer toute ignorance, mais à juger la valeur d’une recherche déterminée."}],"uses":[{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Interroger la valeur inconditionnelle du savoir","reason":"Il faut aussi examiner ce que l’exigence de savoir engage pour la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=73","sourceLabel":"Recueil académique · p. 73"},{"subject":"Savoir rend-il malheureux ?","function":"Déplacer la question vers l’usage du savoir","reason":"La sagesse peut régler la recherche au lieu d’identifier ignorance et bonheur.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=55","sourceLabel":"Recueil académique · p. 55"}]},{"id":"nietzsche-lepreuve-et-la-force","code":"N12","author":"Nietzsche","title":"L’épreuve et la force","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 8","quote":"Ce qui ne me fait pas mourir me rend plus fort.","notions":["bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Une difficulté doit-elle être jugée seulement d’après la souffrance qu’elle inflige ?"},{"function":"L’affirmation","sentence":"Nietzsche affirme à la première personne qu’une épreuve qui ne le détruit pas peut accroître sa force."},{"function":"Les concepts","sentence":"La force désigne ici une puissance de vivre et de surmonter, et non la simple absence de blessure."},{"function":"La raison","sentence":"Une résistance peut nous obliger à développer des capacités qui ne s’exerceraient pas dans une vie entièrement protégée."},{"function":"L’exemple","sentence":"Un échec peut conduire à reprendre un travail et à mieux comprendre ses exigences."},{"function":"La portée","sentence":"La formule invite ainsi à penser la transformation d’une épreuve, mais ne démontre pas que toute souffrance renforce nécessairement celui qui la subit."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer bonheur et absence d’épreuve","reason":"Une vie peut gagner en puissance en traversant une difficulté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Satisfaire ses désirs peut-il rendre malheureux ?","function":"Contester l’évitement de toute frustration","reason":"Le refus immédiat d’un désir peut avoir une valeur formatrice, sans que toute frustration soit bonne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=91","sourceLabel":"Recueil académique · p. 91"}]},{"id":"nietzsche-le-besoin-de-musique","code":"N13","author":"Nietzsche","title":"Le besoin de musique","work":"Le Crépuscule des idoles","locator":"« Maximes et pointes », § 33","quote":"Sans musique la vie serait une erreur.","notions":["art","bonheur"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"La valeur d’une vie se réduit-elle à la satisfaction des besoins indispensables ?"},{"function":"L’affirmation","sentence":"Nietzsche donne à la musique une importance telle qu’une vie qui en serait privée lui paraît manquer son sens."},{"function":"Les concepts","sentence":"L’erreur désigne ici une manière de vivre appauvrie plutôt qu’une proposition intellectuellement fausse."},{"function":"La raison","sentence":"La musique peut donner rythme, intensité et forme à l’expérience, au-delà de ce qui sert seulement à survivre."},{"function":"L’exemple","sentence":"Un chant peut faire éprouver ensemble une joie ou une douleur que la seule description ne ferait pas vivre de la même manière."},{"function":"La portée","sentence":"L’art peut donc appartenir à ce qui rend une existence désirable, sans que chaque œuvre produise le même effet sur chacun."}],"uses":[{"subject":"Avons-nous besoin d’art ?","function":"Défendre un besoin au-delà de la survie","reason":"Une vie humaine ne s’évalue pas seulement à sa conservation matérielle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"L’art est-il un luxe ?","function":"Contester l’idée d’un simple supplément","reason":"La musique peut être comprise comme une composante de la valeur d’une vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"}]},{"id":"nietzsche-la-raison-et-les-sens","code":"N14","author":"Nietzsche","title":"La raison et les sens","work":"Le Crépuscule des idoles","locator":"« La “raison” dans la philosophie », § 2","quote":"Si nous faussons le témoignage des sens, c’est la « raison » qui en est la cause.","notions":["raison","verite"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Les erreurs viennent-elles toujours des sens plutôt que de nos interprétations ?"},{"function":"L’affirmation","sentence":"Nietzsche accuse certaines constructions de la raison de fausser le témoignage sensible."},{"function":"Les concepts","sentence":"Les sens présentent le changement, tandis que la raison visée ici cherche des choses fixes et identiques derrière ce changement."},{"function":"La raison","sentence":"L’erreur peut donc venir de catégories que nous imposons à l’expérience en les prenant pour la réalité elle-même."},{"function":"L’exemple","sentence":"Nommer une chose peut nous inciter à la croire absolument identique alors même que nous en observons les transformations."},{"function":"La portée","sentence":"La critique demande ainsi d’examiner nos manières d’interpréter, sans déclarer que tout raisonnement serait trompeur."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer la dépendance envers le sensible","reason":"L’interprétation doit répondre de ce qu’elle fait au témoignage des sens.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Faut-il ne croire que ce que l’on voit ?","function":"Distinguer perception et interprétation","reason":"L’erreur ne se situe pas nécessairement dans la sensation elle-même.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=103","sourceLabel":"Recueil académique · p. 103"}]},{"id":"nietzsche-la-grammaire-et-la-metaphysique","code":"N15","author":"Nietzsche","title":"La grammaire et la métaphysique","work":"Le Crépuscule des idoles","locator":"« La “raison” dans la philosophie », § 5","quote":"Je crains bien que nous ne nous débarrassions jamais de Dieu, puisque nous croyons encore à la grammaire…","notions":["langage","religion"],"edition":"Œuvres, préface de Patrick Wotling","publisher":"Flammarion","editionYear":2010,"translator":"Henri Albert","commentary":[{"function":"Le problème","sentence":"Abandonner une croyance religieuse suffit-il à abandonner les habitudes de pensée qui lui sont liées ?"},{"function":"L’affirmation","sentence":"Nietzsche soutient que certaines croyances métaphysiques peuvent subsister dans notre confiance envers la grammaire."},{"function":"Les concepts","sentence":"Croire à la grammaire signifie ici prendre la structure de nos phrases pour une description nécessaire de la structure du réel."},{"function":"La raison","sentence":"L’habitude de rapporter une action à un sujet peut nous conduire à supposer derrière tout événement un agent ou une substance qui le produirait."},{"function":"L’exemple","sentence":"Dire « je pense » peut ainsi nous faire traiter le « je » comme une réalité déjà connue, alors que la forme de la phrase ne démontre pas son existence comme substance."},{"function":"La portée","sentence":"La critique doit donc examiner les présupposés de nos formulations, au lieu de croire que supprimer le mot « Dieu » libérerait à lui seul la pensée de toute métaphysique."}],"uses":[{"subject":"Le langage déforme-t-il la pensée ?","function":"Interroger une contrainte inaperçue","reason":"La forme grammaticale peut suggérer des êtres ou des causes qu’il reste à justifier.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=34","sourceLabel":"Recueil académique · p. 34"},{"subject":"Croire, est-ce renoncer à la raison ?","function":"Déplacer l’opposition croyance et rationalité","reason":"La pensée qui se croit délivrée de la croyance peut en conserver certains présupposés.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"},{"subject":"Sommes-nous prisonniers du langage ?","function":"I.2 : renforcer la première réponse","reason":"La grammaire peut imposer à notre pensée des catégories que nous n’avons pas explicitement choisies.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-sommes-nous-prisonniers-du-langage.html","a20Step":"I.2","a20Status":"Une insertion possible dans ce raisonnement ; la citation ne figure pas déjà dans la copie."}]},{"id":"spinoza-liberte-et-necessite","code":"S01","author":"Spinoza","title":"Liberté et nécessité","work":"Éthique","locator":"I, définition 7","quote":"On dit qu’est libre une chose qui existe par la seule nécessité de sa nature et qui n’est déterminée à agir que par elle seule ; mais on appelle nécessaire ou plutôt contrainte celle qui est déterminée par autre chose à exister et à accomplir ses opérations selon une raison précise et déterminée.","notions":["liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Être libre exige-t-il d’échapper à toute nécessité ?"},{"function":"L’affirmation","sentence":"Spinoza définit la liberté par une action qui découle de la nature propre de ce qui agit."},{"function":"Les concepts","sentence":"La nécessité désigne ce qui suit d’une nature, tandis que la contrainte désigne ici une détermination par autre chose."},{"function":"La raison","sentence":"Une action peut donc être nécessaire sans être imposée du dehors, ce que réalise absolument Dieu seul dans ce système."},{"function":"L’exemple","sentence":"Pour l’homme, comprendre les raisons de sa conduite permet de concevoir une autonomie plus grande que la simple obéissance à une impulsion."},{"function":"La portée","sentence":"La liberté humaine se pense ainsi comme un degré d’activité à conquérir, sans faire de l’homme une cause absolument indépendante."}],"uses":[{"subject":"Être libre, est-ce ne se soumettre à rien ?","function":"Redéfinir la liberté","reason":"Distinguer l’absence de toute détermination de la capacité à agir selon des raisons comprises.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Faut-il être raisonnable pour être libre ?","function":"Fonder une autonomie active","reason":"Comprendre ce qui nous détermine peut accroître notre activité, sans supprimer notre dépendance envers la nature.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=41","sourceLabel":"Recueil académique · p. 41"}]},{"id":"spinoza-connaitre-par-les-causes","code":"S02","author":"Spinoza","title":"Connaître par les causes","work":"Éthique","locator":"I, axiome 4","quote":"La connaissance de l’effet dépend de la connaissance de la cause et l’enveloppe.","notions":["science","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Constater qu’un événement se produit suffit-il à le connaître ?"},{"function":"L’affirmation","sentence":"Spinoza lie la connaissance de l’effet à celle de ce qui le produit."},{"function":"Les concepts","sentence":"La cause désigne ce dont l’effet suit, et non un événement qui le précède simplement dans le temps."},{"function":"La raison","sentence":"Comprendre pourquoi une chose existe demande de saisir la relation qui rend compte de sa production."},{"function":"L’exemple","sentence":"Observer la dilatation d’un métal ne l’explique pas encore si l’on ignore le rôle de son échauffement."},{"function":"La portée","sentence":"Cet axiome donne ainsi à la connaissance une exigence explicative qui dépasse le seul relevé des faits."}],"uses":[{"subject":"Connaître est-ce nécessairement expliquer ?","function":"Défendre une connaissance explicative","reason":"Connaître un effet exige ici de comprendre sa production, au-delà de sa seule description.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"},{"subject":"Prévoir, est-ce expliquer ?","function":"Distinguer prévision et causalité","reason":"Une régularité peut permettre une prévision sans donner encore la connaissance de la cause.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"}]},{"id":"spinoza-l-erreur-comme-connaissance-partielle","code":"S03","author":"Spinoza","title":"L’erreur comme connaissance partielle","work":"Éthique","locator":"II, proposition 35","quote":"La fausseté consiste en une privation de connaissance qu’enveloppent les idées inadéquates, autrement dit mutilées et confuses.","notions":["verite","conscience"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une idée fausse est-elle dépourvue de tout rapport au réel ?"},{"function":"L’affirmation","sentence":"Spinoza situe la fausseté dans ce qui manque à une idée pour être adéquate."},{"function":"Les concepts","sentence":"Une idée inadéquate donne une connaissance partielle dont nous ne saisissons pas suffisamment les causes et les relations."},{"function":"La raison","sentence":"Elle peut donc exprimer une affection réelle tout en nous trompant lorsque nous la prenons pour une connaissance complète de son objet."},{"function":"L’exemple","sentence":"Le Soleil paraît proche même à celui qui connaît sa distance, mais celui-ci ne confond plus cette apparence avec une mesure."},{"function":"La portée","sentence":"Corriger l’erreur consiste alors à compléter et à situer nos représentations, sans exiger la disparition de toutes les apparences."}],"uses":[{"subject":"L’ignorance est-elle la seule cause de nos erreurs ?","function":"Préciser le manque qui fait erreur","reason":"L’erreur ne se réduit pas à ne rien savoir : elle implique une représentation partielle dont la limite nous échappe.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Dissiper une illusion, est-ce seulement corriger une erreur ?","function":"Distinguer apparence et jugement","reason":"La connaissance peut corriger le jugement alors que l’apparence sensible persiste.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"}]},{"id":"spinoza-se-connaitre-par-le-corps","code":"S04","author":"Spinoza","title":"Se connaître par le corps","work":"Éthique","locator":"II, proposition 23","quote":"L’esprit ne se connaît pas lui-même, sinon en tant qu’il perçoit les idées des affections du corps.","notions":["conscience","nature"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La connaissance de soi vient-elle d’un regard intérieur indépendant du corps ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que l’esprit se connaît à travers les idées des modifications corporelles."},{"function":"Les concepts","sentence":"Une affection est ici une modification du corps, dont l’esprit forme une idée et peut percevoir cette idée."},{"function":"La raison","sentence":"L’esprit étant l’idée du corps, sa connaissance de lui-même passe par les manières dont ce corps est affecté."},{"function":"L’exemple","sentence":"Éprouver puis reconnaître sa peur engage ainsi la perception de changements corporels, et pas seulement un jugement abstrait sur soi."},{"function":"La portée","sentence":"La conscience de soi se construit donc dans une expérience incarnée, sans garantir une connaissance complète de ses causes."}],"uses":[{"subject":"Être conscient, est-ce savoir ?","function":"Limiter la transparence à soi","reason":"Percevoir ce que l’on éprouve donne une conscience de soi, sans suffire à en connaître adéquatement les causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"Peut-on penser sans sentir ?","function":"Montrer le rôle du corps","reason":"La connaissance de soi passe ici par les idées des affections corporelles plutôt que par un esprit isolé.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"}]},{"id":"spinoza-perseverer-dans-son-etre","code":"S05","author":"Spinoza","title":"Persévérer dans son être","work":"Éthique","locator":"III, proposition 6","quote":"Abstraction faite du reste, chaque chose s’efforce de persévérer dans son être.","notions":["nature","liberte"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Le désir humain s’explique-t-il seulement par ce qui nous manque ?"},{"function":"L’affirmation","sentence":"Spinoza inscrit l’effort humain dans une tendance de chaque chose à persévérer dans son être."},{"function":"Les concepts","sentence":"Cet effort, appelé conatus, désigne une puissance effective d’exister et d’agir, sans supposer un projet conscient chez toute chose."},{"function":"La raison","sentence":"Considérée en elle-même, une chose affirme sa nature, tandis que sa destruction vient de causes qui lui sont contraires."},{"function":"L’exemple","sentence":"Un organisme qui répare une blessure manifeste une activité de conservation sans devoir se représenter une fin."},{"function":"La portée","sentence":"Le désir peut ainsi être compris à partir d’une puissance positive, sans nier les obstacles extérieurs qui la limitent."}],"uses":[{"subject":"Ne désirons-nous que ce qui nous manque ?","function":"Contester une définition par le manque","reason":"L’effort de vivre et d’agir exprime une puissance présente, même lorsqu’il rencontre une privation.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"},{"subject":"Le désir est-il un obstacle à la liberté ?","function":"Écarter la suppression de tout désir","reason":"Si le désir exprime notre effort d’exister, la liberté doit transformer sa conduite plutôt que supprimer cet effort.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=43","sourceLabel":"Recueil académique · p. 43"}]},{"id":"spinoza-le-desir-et-le-jugement-de-valeur","code":"S06","author":"Spinoza","title":"Le désir et le jugement de valeur","work":"Éthique","locator":"III, proposition 9, scolie","quote":"Au contraire, si nous jugeons qu’une chose est bonne, c’est parce que nous faisons effort vers elle, que nous la voulons, que nous y aspirons, que nous la désirons.","notions":["raison","devoir"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Jugeons-nous une chose bonne avant de la désirer ?"},{"function":"L’affirmation","sentence":"Spinoza renverse cet ordre en faisant du désir le principe de notre jugement de valeur."},{"function":"Les concepts","sentence":"Le bon désigne ici ce que notre effort nous porte à rechercher, plutôt qu’une qualité reconnue indépendamment de toute aspiration."},{"function":"La raison","sentence":"Nos évaluations expriment ainsi une manière d’être affectés et de poursuivre ce qui nous paraît favorable."},{"function":"L’exemple","sentence":"Un aliment paraît précieux à celui qui a faim alors qu’il laisse indifférent celui qui est rassasié."},{"function":"La portée","sentence":"Ce renversement invite à examiner nos désirs, sans conclure que tous les objets désirés sont réellement utiles ou également bons."}],"uses":[{"subject":"Ne désirons-nous que les choses que nous estimons bonnes ?","function":"Renverser le rapport entre désir et valeur","reason":"Examiner si notre jugement motive le désir ou exprime déjà une aspiration.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=92","sourceLabel":"Recueil académique · p. 92"},{"subject":"Le désir est-il aveugle ?","function":"Interroger l’indépendance de nos jugements","reason":"Un jugement apparemment réfléchi peut traduire un désir dont nous ne connaissons pas les causes.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=90","sourceLabel":"Recueil académique · p. 90"}]},{"id":"spinoza-la-joie-et-la-puissance-d-agir","code":"S07","author":"Spinoza","title":"La joie et la puissance d’agir","work":"Éthique","locator":"IV, proposition 41","quote":"La joie, directement, n’est pas mauvaise, mais bonne ; la tristesse, au contraire, est directement mauvaise.","notions":["bonheur","devoir"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La joie a-t-elle seulement une valeur agréable et subjective ?"},{"function":"L’affirmation","sentence":"Spinoza la dit directement bonne et attribue à la tristesse la valeur contraire."},{"function":"Les concepts","sentence":"La joie est un passage à une puissance d’agir plus grande, tandis que la tristesse marque une diminution de cette puissance."},{"function":"La raison","sentence":"Leur valeur directe dépend de cette variation de nos capacités, et pas simplement d’une préférence pour des sensations plaisantes."},{"function":"L’exemple","sentence":"La joie de comprendre une difficulté peut rendre possible un travail qui paraissait jusque-là hors de portée."},{"function":"La portée","sentence":"Cette valeur directe ne rend pourtant pas toute joie bonne dans toutes ses conséquences, car certaines satisfactions partielles peuvent être excessives."}],"uses":[{"subject":"Faut-il chercher le bonheur à tout prix ?","function":"Distinguer joie et satisfaction immédiate","reason":"Le gain de puissance permet d’évaluer une joie, puis d’examiner ses effets au-delà de son agrément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Obéir à la raison suffit-il à rendre heureux ?","function":"Relier raison et vie affective","reason":"La raison peut soutenir une joie active : vivre raisonnablement ne signifie pas vivre sans affects.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"}]},{"id":"spinoza-transformer-les-affects","code":"S08","author":"Spinoza","title":"Transformer les affects","work":"Éthique","locator":"IV, proposition 7","quote":"Un affect ne peut être ni contrarié, ni supprimé, sinon par un affect contraire et plus fort que l’affect à contrarier.","notions":["liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une simple décision suffit-elle à vaincre une passion ?"},{"function":"L’affirmation","sentence":"Spinoza affirme qu’un affect ne cède que devant un affect contraire dont la force le dépasse."},{"function":"Les concepts","sentence":"Un affect est une modification qui augmente ou diminue notre puissance d’agir, accompagnée de son idée."},{"function":"La raison","sentence":"Une consigne abstraite ne change donc pas une passion tant qu’elle ne prend pas elle-même une force dans notre vie affective."},{"function":"L’exemple","sentence":"Le plaisir effectif d’un travail partagé peut ainsi contrarier une envie de renoncer plus efficacement qu’un ordre sans prise sur nous."},{"function":"La portée","sentence":"La maîtrise de soi exige alors une transformation des affects, où la raison agit par des désirs et des joies qu’elle fait naître."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Préciser les moyens de la libération","reason":"On ne combat pas une passion depuis une volonté sans affects : il faut construire une force contraire.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"N’y a-t-il que des passions déraisonnables ?","function":"Distinguer affect et passion","reason":"La raison produit aussi des affects actifs, capables de transformer ceux que nous subissons.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}]},{"id":"spinoza-un-bien-qui-se-partage","code":"S09","author":"Spinoza","title":"Un bien qui se partage","work":"Éthique","locator":"IV, proposition 36","quote":"Le bien suprême de ceux qui poursuivent la vertu est commun à tous, et tout le monde peut s’en réjouir à égalité.","notions":["bonheur","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Le bien des autres diminue-t-il nécessairement le mien ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que le bien suprême de la vie vertueuse peut être partagé par tous."},{"function":"Les concepts","sentence":"Ce bien est la connaissance de Dieu, c’est-à-dire la compréhension de la réalité dont nous faisons partie, et la vertu est une puissance d’agir."},{"function":"La raison","sentence":"Comprendre ne prive personne de comprendre, contrairement à la possession exclusive d’un objet rare."},{"function":"L’exemple","sentence":"Lorsqu’un élève explique une démonstration à un camarade, le second peut la comprendre sans retirer au premier son savoir."},{"function":"La portée","sentence":"Un bien commun devient donc pensable au-delà de la rivalité, sans supposer que tous les biens matériels se partagent de cette manière."}],"uses":[{"subject":"Peut-on faire le bonheur d’autrui ?","function":"Dépasser la rivalité des intérêts","reason":"Partager une compréhension peut contribuer à la joie d’autrui sans en faire un état que l’on pourrait lui imposer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La raison n’a-t-elle pour fin que la connaissance du réel ?","function":"Montrer une portée éthique du connaître","reason":"La compréhension peut constituer un bien partageable et transformer nos rapports avec les autres.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"}]},{"id":"spinoza-agir-par-raison-ou-par-peur","code":"S10","author":"Spinoza","title":"Agir par raison ou par peur","work":"Éthique","locator":"IV, proposition 63","quote":"Qui est conduit par la crainte, et fait le bien pour éviter le mal, n’est pas conduit par la raison.","notions":["devoir","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Une conduite conforme au bien est-elle nécessairement raisonnable ?"},{"function":"L’affirmation","sentence":"Spinoza distingue l’action conduite par la crainte de celle qui naît de la raison."},{"function":"Les concepts","sentence":"La crainte nous fait fuir un mal incertain, tandis que la raison nous porte directement vers ce qui accroît notre puissance."},{"function":"La raison","sentence":"Un même comportement peut donc provenir de motifs différents, selon que nous comprenons son utilité ou redoutons une peine."},{"function":"L’exemple","sentence":"Respecter une règle par peur d’être puni diffère de la respecter parce qu’on comprend la protection qu’elle assure à chacun."},{"function":"La portée","sentence":"La valeur rationnelle d’une conduite demande ainsi l’examen de son principe, au-delà de sa seule conformité extérieure."}],"uses":[{"subject":"Obéir, est-ce nécessairement se soumettre ?","function":"Distinguer conformité et motif","reason":"Distinguer l’obéissance motivée par la peur de celle qui procède de la compréhension du bien poursuivi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=39","sourceLabel":"Recueil académique · p. 39"},{"subject":"Faut-il être raisonnable pour être libre ?","function":"Critiquer une obéissance dominée par la peur","reason":"Une conduite prudente en apparence peut rester sous la dépendance d’une passion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=41","sourceLabel":"Recueil académique · p. 41"}]},{"id":"spinoza-une-sagesse-de-la-vie","code":"S11","author":"Spinoza","title":"Une sagesse de la vie","work":"Éthique","locator":"IV, proposition 67","quote":"L’homme libre ne pense à rien moins qu’à la mort, et sa sagesse est une méditation non de la mort, mais de la vie.","notions":["bonheur","liberte","temps"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La sagesse doit-elle se construire autour de la peur de mourir ?"},{"function":"L’affirmation","sentence":"Spinoza définit la sagesse de l’homme libre par une méditation de la vie."},{"function":"Les concepts","sentence":"L’expression ne penser à rien moins qu’à la mort signifie que la mort est ce qui occupe le moins sa pensée."},{"function":"La raison","sentence":"Conduit par la raison, cet homme recherche directement ce qui lui permet de vivre et d’agir plutôt que de fuir seulement un mal."},{"function":"L’exemple","sentence":"Prendre soin de sa santé peut ainsi viser les activités que l’on aime accomplir au lieu de devenir une obsession de sa fin."},{"function":"La portée","sentence":"La lucidité sur notre condition mortelle ne disparaît pas, mais la crainte de la mort cesse de commander toute l’existence."}],"uses":[{"subject":"Pourquoi craindre la mort ?","function":"Contester le rôle directeur de la crainte","reason":"La sagesse peut reconnaître la mortalité tout en prenant pour objet principal la puissance de vivre.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=143","sourceLabel":"Recueil académique · p. 143"},{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Déplacer l’obstacle vers notre rapport à la mort","reason":"La finitude n’empêche pas toute joie, tandis que la peur peut envahir la vie présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"}]},{"id":"spinoza-la-liberte-dans-la-cite","code":"S12","author":"Spinoza","title":"La liberté dans la cité","work":"Éthique","locator":"IV, proposition 73","quote":"L’homme conduit par la raison est plus libre dans la cité où il vit par décision commune, que dans la solitude où il n’obéit qu’à lui seul.","notions":["etat","liberte"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Être libre demande-t-il de vivre sans dépendre des autres ?"},{"function":"L’affirmation","sentence":"Spinoza affirme qu’une vie réglée en commun peut rendre l’homme raisonnable plus libre que la solitude."},{"function":"Les concepts","sentence":"La cité désigne une organisation politique, et la liberté une puissance d’agir guidée par la raison plutôt qu’une absence de liens."},{"function":"La raison","sentence":"La coopération et des droits communs soutiennent des capacités qu’un individu isolé ne pourrait exercer aussi sûrement."},{"function":"L’exemple","sentence":"Une règle commune protégeant chacun de la violence permet des activités que la seule force individuelle ne garantirait pas."},{"function":"La portée","sentence":"L’obéissance peut donc servir la liberté, sous réserve d’examiner les institutions réelles et sans justifier toute domination politique."}],"uses":[{"subject":"La liberté exclut-elle l’obéissance ?","function":"Distinguer obéissance et servitude","reason":"Obéir à une décision commune peut protéger une puissance d’agir au lieu de l’annuler.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"},{"subject":"Être seul, est-ce être libre ?","function":"Renverser l’idéal d’indépendance","reason":"La solitude supprime certains liens mais prive aussi des moyens d’agir que procure la vie commune.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=42","sourceLabel":"Recueil académique · p. 42"}]},{"id":"spinoza-comprendre-une-passion","code":"S13","author":"Spinoza","title":"Comprendre une passion","work":"Éthique","locator":"V, proposition 3","quote":"Un affect qui est une passion cesse d’être une passion, sitôt que nous en formons une idée claire et distincte.","notions":["conscience","liberte","raison"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Comprendre ce que nous éprouvons peut-il modifier ce que nous subissons ?"},{"function":"L’affirmation","sentence":"Spinoza soutient qu’une connaissance claire de l’affect lui retire son caractère passif."},{"function":"Les concepts","sentence":"La passion est un affect dont nous ne sommes qu’une cause partielle, et son idée demeure confuse."},{"function":"La raison","sentence":"Former une idée adéquate transforme notre rapport à cet affect en y introduisant une activité de compréhension."},{"function":"L’exemple","sentence":"Identifier précisément les mécanismes de sa colère peut permettre d’agir sur la situation au lieu d’en accuser aveuglément une personne."},{"function":"La portée","sentence":"La compréhension devient ainsi un moyen de libération, sans promettre que nommer une émotion suffise à la connaître ni que toute émotion disparaisse."}],"uses":[{"subject":"Faut-il combattre les passions pour être libre ?","function":"Remplacer la répression par la compréhension","reason":"La passion peut être transformée par une activité de connaissance plutôt que combattue comme une force étrangère.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=45","sourceLabel":"Recueil académique · p. 45"},{"subject":"Est-ce l’ignorance de ce que nous sommes qui fait la force de nos passions ?","function":"Établir un lien entre confusion et passivité","reason":"Comprendre l’affect change la manière dont nous en sommes affectés, au-delà d’une simple prise de conscience.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=131","sourceLabel":"Recueil académique · p. 131"}]},{"id":"spinoza-comprendre-la-necessite","code":"S14","author":"Spinoza","title":"Comprendre la nécessité","work":"Éthique","locator":"V, proposition 6","quote":"En tant que l’esprit comprend toutes choses comme nécessaires, il a par là une plus grande puissance sur les affects, autrement dit, il pâtit moins d’eux.","notions":["liberte","raison","bonheur"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"Comprendre la nécessité nous condamne-t-il à subir davantage ?"},{"function":"L’affirmation","sentence":"Spinoza affirme au contraire que cette compréhension augmente notre puissance sur les affects."},{"function":"Les concepts","sentence":"La nécessité désigne l’enchaînement des causes qui produit les choses, tandis que pâtir signifie dépendre de causes que nous ne maîtrisons pas."},{"function":"La raison","sentence":"Comprendre cet enchaînement réduit les représentations confuses qui nourrissent certains regrets, certaines colères et certaines attentes impossibles."},{"function":"L’exemple","sentence":"Comprendre qu’une perte ne pouvait être évitée peut atténuer le regret qui la redouble, sans effacer immédiatement la tristesse."},{"function":"La portée","sentence":"La connaissance peut donc transformer notre manière de vivre ce qui arrive, sans nous donner le pouvoir de tout empêcher."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Montrer un effet pratique de la compréhension","reason":"Connaître les causes peut transformer notre rapport à une épreuve, même lorsque l’événement lui-même échappe à notre pouvoir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Obéir à la raison suffit-il à rendre heureux ?","function":"Établir un progrès sans garantir une invulnérabilité","reason":"Comprendre diminue certaines dépendances affectives, mais ne supprime pas notre exposition aux causes extérieures.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=14","sourceLabel":"Recueil académique · p. 14"},{"subject":"Faut-il être inconscient pour être heureux ?","function":"III.2 : faire du savoir une ressource contre la peur","reason":"Prolonger l’examen de la crainte par la compréhension des causes : elle peut diminuer certains regrets, sans faire disparaître toute douleur.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-faut-il-etre-inconscient-pour-etre-heureux.html","a20Step":"III.2","a20Status":"Insertion proposée après lecture de la copie ; citation absente du modèle."}]},{"id":"spinoza-l-ordre-des-idees-et-des-choses","code":"S15","author":"Spinoza","title":"L’ordre des idées et des choses","work":"Éthique","locator":"II, proposition 7","quote":"L’ordre et enchaînement des idées est le même que l’ordre et enchaînement des choses.","notions":["nature","raison","science"],"edition":"Éthique, édition de Maxime Rovere","publisher":"Flammarion","editionYear":"2021","translator":"Maxime Rovere","commentary":[{"function":"Le problème","sentence":"La pensée et les choses appartiennent-elles à deux mondes sans rapport ?"},{"function":"L’affirmation","sentence":"Spinoza affirme que leurs enchaînements expriment un même ordre."},{"function":"Les concepts","sentence":"Les idées sont des modes de la pensée, tandis que les choses se comprennent sous les attributs dont elles relèvent."},{"function":"La raison","sentence":"Une même réalité s’exprime selon ces attributs sans qu’il faille supposer une action de la pensée sur l’étendue ou de l’étendue sur la pensée."},{"function":"L’exemple","sentence":"Un événement corporel et son idée se comprennent ainsi comme deux expressions d’une même réalité, et non comme deux événements qui se commanderaient du dehors."},{"function":"La portée","sentence":"Cette thèse fonde l’intelligibilité du réel, sans prétendre que toutes nos représentations particulières en donnent une connaissance adéquate."}],"uses":[{"subject":"La raison suffit-elle à connaître le réel ?","function":"Fonder la possibilité d’une connaissance rationnelle","reason":"Le réel présente un ordre intelligible, mais il reste à établir que nos idées particulières le saisissent adéquatement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"L’activité de l’esprit s’explique-t-elle par des causes matérielles ?","function":"Distinguer unité et réduction","reason":"Le même ordre s’exprime sous la pensée et l’étendue sans faire d’un événement matériel la cause d’une idée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=99","sourceLabel":"Recueil académique · p. 99"}]},{"id":"cioran-les-faux-absolus","code":"C01","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les faux absolus","work":"Précis de décomposition","locator":"« Généalogie du fanatisme »","quote":"L’histoire n’est qu’un défilé de faux Absolus, une succession de temples élevés à des prétextes, un avilissement de l’esprit devant l’improbable.","notions":["religion","raison"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Abandonner une religion suffit-il à se libérer de toute croyance absolue ?"},{"function":"L’affirmation","sentence":"Cioran présente l’histoire comme une succession d’objets humains transformés en absolus."},{"function":"Les concepts","sentence":"Un faux absolu est ici une valeur ou une cause particulière soustraite à toute discussion et adorée comme une divinité."},{"function":"La raison","sentence":"Le besoin de croire peut donc déplacer sa ferveur vers une nation, une classe ou une idée sans changer de fonctionnement."},{"function":"L’exemple","sentence":"Une cause politique devient ainsi une idole lorsque toute objection passe pour une trahison."},{"function":"La portée","sentence":"Cette image dénonce une possibilité du fanatisme, mais sa généralisation polémique ne démontre pas que toute conviction ou toute histoire se réduise à ce mécanisme."}],"uses":[{"subject":"L’esprit religieux ne se manifeste-t-il que dans les religions ?","function":"Déplacer la frontière du religieux","reason":"Interroger les formes de sacralisation qui survivent dans des idéologies se déclarant étrangères à la religion.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"L’histoire enseigne-t-elle la relativité des valeurs ?","function":"Mettre à distance les valeurs proclamées absolues","reason":"La succession des causes sacralisées invite à examiner leur prétention à une validité inconditionnelle.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=106","sourceLabel":"Recueil académique · p. 106"},{"subject":"Peut-on concevoir une humanité sans religion ?","function":"II.3 : limiter la force du lien religieux","reason":"Une communauté peut transformer sa croyance commune en absolu et exclure la contestation ; une idéologie séculière peut reproduire ce mécanisme.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517529.pdf#page=2","sourceLabel":"Bac 2026 · Antilles et Guyane","a20":"philosophie-bac-2026-peut-on-concevoir-une-humanite-sans-religion.html","a20Step":"II.3","a20Status":"Insertion possible après lecture de la copie ; citation absente du modèle."}]},{"id":"cioran-les-mots-et-la-presence-des-choses","code":"C02","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les mots et la présence des choses","work":"Précis de décomposition","locator":"« Dans le cimetière des définitions »","quote":"Sous chaque formule gît un cadavre : l’être ou l’objet meurt sous le prétexte auquel ils ont donné lieu.","notions":["langage","verite"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Une formule rend-elle compte d’une chose ou risque-t-elle de s’y substituer ?"},{"function":"L’affirmation","sentence":"Cioran décrit la définition comme une opération qui peut faire disparaître la présence vivante de son objet."},{"function":"Les concepts","sentence":"Le cadavre est une métaphore de la chose réduite à ce que notre formule en retient, et non détruite matériellement."},{"function":"La raison","sentence":"Lorsque l’esprit prend sa définition pour la réalité entière, il néglige ce que la rencontre sensible et singulière lui faisait éprouver."},{"function":"L’exemple","sentence":"Réduire une personne à une étiquette peut ainsi empêcher d’écouter ce qui, dans sa conduite, dément cette étiquette."},{"function":"La portée","sentence":"La formule oblige à éprouver nos mots au contact des choses, sans établir que toute définition soit inutile ou nécessairement trompeuse."}],"uses":[{"subject":"Le langage nous éloigne-t-il du réel ?","function":"Analyser le risque de substitution","reason":"Un énoncé peut devenir un écran lorsqu’il remplace l’attention portée à ce qu’il désigne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=36","sourceLabel":"Recueil académique · p. 36"},{"subject":"Le langage peut-il être un obstacle à la recherche de la vérité ?","function":"Critiquer une définition figée","reason":"Il faut distinguer l’outil qui permet de chercher de la formule qui prétend clore la recherche.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=35","sourceLabel":"Recueil académique · p. 35"}]},{"id":"cioran-l-ennui-et-le-sens-de-vivre","code":"C03","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’ennui et le sens de vivre","work":"Précis de décomposition","locator":"« Désarticulation du temps »","quote":"La vie se crée dans le délire et se défait dans l’ennui.","notions":["bonheur","temps"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le repos et l’absence de difficultés suffisent-ils à donner le sentiment de vivre ?"},{"function":"L’affirmation","sentence":"Cioran oppose l’élan qui peuple la vie de significations à l’ennui qui les défait."},{"function":"Les concepts","sentence":"Le délire désigne ici nos investissements excessifs dans des désirs et des valeurs, tandis que l’ennui les prive de leur évidence."},{"function":"La raison","sentence":"Lorsque plus rien ne nous attire, les instants continuent de passer mais cessent de porter des possibilités auxquelles nous tenons."},{"function":"L’exemple","sentence":"Une journée entièrement libre peut ainsi paraître interminable si aucun projet ne rend ses moments désirables."},{"function":"La portée","sentence":"L’opposition éclaire la fragilité du sens vécu, sans faire de tout engagement une maladie ni de tout repos un vide."}],"uses":[{"subject":"Le bonheur se trouve-t-il dans le repos ?","function":"Limiter l’idéal d’absence de trouble","reason":"Le repos ne suffit pas si la disparition des préoccupations retire aussi tout intérêt à ce que l’on vit.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Un bonheur sans illusion est-il concevable ?","function":"Interroger le rôle des attachements","reason":"Examiner si le sentiment de vivre dépend de valeurs investies au-delà de ce qu’une lucidité critique peut garantir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-expliquer-et-vivre","code":"C04","author":"Cioran","authorRole":"Écrivain et penseur","title":"Expliquer et vivre","work":"Précis de décomposition","locator":"« Adieu à la philosophie »","quote":"On ne peut éluder l’existence par des explications, on ne peut que la subir, l’aimer ou la haïr, l’adorer ou la craindre, dans cette alternance de félicité et d’horreur qui exprime le rythme même de l’être, ses oscillations, ses dissonances, ses véhémences amères ou allègres.","notions":["raison","bonheur"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Comprendre pourquoi nous souffrons suffit-il à nous dispenser de vivre cette souffrance ?"},{"function":"L’affirmation","sentence":"Cioran conteste le pouvoir des explications de nous soustraire à l’épreuve de l’existence."},{"function":"Les concepts","sentence":"Éluder signifie esquiver, tandis qu’expliquer consiste à rendre intelligible ce qui arrive plutôt qu’à l’éprouver à notre place."},{"function":"La raison","sentence":"Une théorie peut décrire une situation sans supprimer les sentiments contradictoires dans lesquels nous la traversons."},{"function":"L’exemple","sentence":"Connaître les mécanismes du deuil ne fait pas disparaître immédiatement la douleur d’une perte."},{"function":"La portée","sentence":"Cette critique limite la prétention du savoir à nous délivrer de toute épreuve, sans prouver qu’une explication ne puisse jamais nous aider à vivre."}],"uses":[{"subject":"Les connaissances nous aident-elles à vivre ?","function":"Limiter le pouvoir du savoir","reason":"Comprendre une épreuve ne dispense pas de la traverser ; il reste à préciser en quoi la compréhension peut néanmoins aider.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"La raison peut-elle tout expliquer ?","function":"Distinguer explication et expérience","reason":"Même une explication étendue ne remplace pas l’expérience vécue, ce qui ne constitue pas à soi seul une réfutation de cette explication.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=49","sourceLabel":"Recueil académique · p. 49"}]},{"id":"cioran-les-desirs-dementent-nos-principes","code":"C05","author":"Cioran","authorRole":"Écrivain et penseur","title":"Les désirs démentent nos principes","work":"Précis de décomposition","locator":"« Cosmogonie du désir »","quote":"Chaque désir humilie la somme de nos vérités et nous oblige à reconsidérer nos négations.","notions":["raison","liberte"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Nos conclusions intellectuelles commandent-elles effectivement nos désirs ?"},{"function":"L’affirmation","sentence":"Cioran montre le désir revenant contredire les raisons par lesquelles nous prétendions nous détacher de la vie."},{"function":"Les concepts","sentence":"Les vérités et les négations désignent ici les conclusions pessimistes du narrateur, tandis que le désir marque la persistance de son attachement."},{"function":"La raison","sentence":"Le corps peut continuer de vouloir ce que l’esprit avait déclaré vain, révélant un écart entre conviction théorique et conduite effective."},{"function":"L’exemple","sentence":"Celui qui proclame l’inutilité des honneurs peut encore attendre avec impatience un signe de reconnaissance."},{"function":"La portée","sentence":"Le désir éprouve ainsi la portée pratique de nos principes, sans que sa force suffise à démontrer leur fausseté logique."}],"uses":[{"subject":"La raison s’oppose-t-elle nécessairement au désir ?","function":"Analyser un conflit sans le généraliser","reason":"Les raisons de se détacher peuvent échouer à éteindre un attachement, ce qui ne condamne pas toute alliance entre raison et désir.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=51","sourceLabel":"Recueil académique · p. 51"},{"subject":"Peut-on être en conflit avec soi-même ?","function":"Distinguer jugement et attachement","reason":"Un même individu peut soutenir une conclusion et continuer de désirer ce qu’elle dévalue.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"cioran-reflechir-transforme-la-sensation","code":"C06","author":"Cioran","authorRole":"Écrivain et penseur","title":"Réfléchir transforme la sensation","work":"Précis de décomposition","locator":"« Visages de la décadence »","quote":"Méditer ses sensations – savoir que l’on mange, – c’est là une prise de conscience grâce à laquelle un acte élémentaire dépasse son but immédiat.","notions":["conscience","nature"],"edition":"Précis de décomposition (première publication)","publisher":"Gallimard","editionYear":"1949","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La conscience accompagne-t-elle seulement nos actes ou en transforme-t-elle la signification ?"},{"function":"L’affirmation","sentence":"Cioran affirme que l’attention portée à une sensation modifie un acte aussi élémentaire que manger."},{"function":"Les concepts","sentence":"Le but immédiat est ici de se nourrir, tandis que méditer sa sensation fait du repas un objet de réflexion et de recherche."},{"function":"La raison","sentence":"L’acte ne se limite plus à satisfaire un besoin lorsque l’esprit s’intéresse à la qualité et aux variations de ce qu’il éprouve."},{"function":"L’exemple","sentence":"Comparer lentement des saveurs introduit ainsi une recherche du goût au-delà de la seule faim."},{"function":"La portée","sentence":"Dans ce passage sur la décadence, ce raffinement reste ambivalent et ne vaut donc pas comme preuve que toute réflexion améliore la vie."}],"uses":[{"subject":"Sommes-nous conscients ou le devenons-nous ?","function":"Distinguer vécu immédiat et réflexion","reason":"La prise de conscience peut modifier le sens d’un acte déjà accompli sans attention réfléchie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"La conscience de ce que nous sommes peut-elle faire obstacle à notre bonheur ?","function":"Interroger les effets du retour sur soi","reason":"La réflexion enrichit parfois une sensation, mais peut aussi compliquer et inquiéter ce qui se faisait spontanément.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-le-doute-et-la-vie-commune","code":"C07","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le doute et la vie commune","work":"La Chute dans le temps","locator":"« Le sceptique et le barbare »","quote":"Une civilisation débute par le mythe et finit dans le doute ; doute théorique qui, lorsqu’elle le retourne contre elle-même, s’achève en doute pratique.","notions":["raison","verite"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La critique des croyances peut-elle finir par atteindre notre capacité d’agir ?"},{"function":"L’affirmation","sentence":"Cioran décrit une civilisation dont le doute passe de l’examen des idées à l’incertitude sur ses propres fins."},{"function":"Les concepts","sentence":"Le doute théorique porte sur ce que l’on tient pour vrai, tandis que le doute pratique atteint les valeurs qui orientent les actes."},{"function":"La raison","sentence":"Lorsqu’une communauté ne reconnaît plus aucun motif de préférer une fin à une autre, sa lucidité peut se convertir en impuissance."},{"function":"L’exemple","sentence":"Un groupe qui remet indéfiniment en question toutes ses raisons de décider peut ne plus parvenir à choisir une action commune."},{"function":"La portée","sentence":"Ce schéma tragique interroge le coût d’un doute généralisé, sans constituer une loi démontrée de la naissance et de la mort de toutes les civilisations."}],"uses":[{"subject":"Douter, est-ce renoncer à la vérité ?","function":"Distinguer examen et désorientation","reason":"Le doute peut servir la recherche, mais son extension à toute raison de juger peut retirer à cette recherche sa direction.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=71","sourceLabel":"Recueil académique · p. 71"},{"subject":"Peut-on ne croire en rien ?","function":"Examiner les conditions de l’action","reason":"Une suspension totale des convictions pose la question des raisons qui permettraient encore de décider.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=83","sourceLabel":"Recueil académique · p. 83"}]},{"id":"cioran-convertir-et-contraindre","code":"C08","author":"Cioran","authorRole":"Écrivain et penseur","title":"Convertir et contraindre","work":"La Chute dans le temps","locator":"« Portrait du civilisé »","quote":"Ce n’est point pour libérer, c’est pour enchaîner qu’on s’applique à convertir.","notions":["religion","liberte"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Vouloir faire adopter sa conviction revient-il toujours à servir la liberté d’autrui ?"},{"function":"L’affirmation","sentence":"Cioran soupçonne la conversion de prolonger une volonté de soumettre sous une promesse de libération."},{"function":"Les concepts","sentence":"Convertir signifie faire adhérer à une croyance, et la chaîne figure ici une dépendance imposée au jugement."},{"function":"La raison","sentence":"Celui qui ne supporte pas sa propre discipline peut vouloir la généraliser plutôt que reconnaître à un autre la possibilité de s’en passer."},{"function":"L’exemple","sentence":"Une doctrine devient contraignante lorsque celui qui prétend sauver autrui lui retire le droit de refuser son salut."},{"function":"La portée","sentence":"La formule démasque une logique possible du prosélytisme, mais son absoluité polémique ne suffit pas à identifier toute transmission d’une croyance à une oppression."}],"uses":[{"subject":"La religion unit-elle ou sépare-t-elle les hommes ?","function":"Interroger les conditions du rassemblement","reason":"L’union autour d’une croyance peut devenir une exigence d’uniformité qui exclut le refus et la différence.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=53","sourceLabel":"Recueil académique · p. 53"},{"subject":"La liberté exclut-elle l’obéissance ?","function":"Critiquer une soumission présentée comme un salut","reason":"Il faut examiner si l’adhésion conserve la possibilité de juger et de refuser, au-delà de la liberté annoncée.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=38","sourceLabel":"Recueil académique · p. 38"}]},{"id":"cioran-l-assurance-et-le-besoin-d-eloge","code":"C09","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’assurance et le besoin d’éloge","work":"La Chute dans le temps","locator":"« Désir et horreur de la gloire »","quote":"En apparence, tout le monde est content de soi ; en réalité, personne.","notions":["conscience","bonheur"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"L’assurance que nous montrons aux autres prouve-t-elle que nous sommes satisfaits de nous-mêmes ?"},{"function":"L’affirmation","sentence":"Cioran oppose l’image publique de la satisfaction à une insécurité intérieure que l’éloge vient apaiser."},{"function":"Les concepts","sentence":"L’apparence désigne ce que nous affichons, tandis que le contentement de soi désigne ici une estime assez stable pour ne plus chercher de confirmation."},{"function":"La raison","sentence":"Le besoin persistant de compliments peut révéler une dépendance au jugement d’autrui jusque chez celui qui se dit supérieur à ce jugement."},{"function":"L’exemple","sentence":"Une personne affichant son indifférence aux critiques peut pourtant attendre avec impatience des félicitations."},{"function":"La portée","sentence":"La symétrie provocatrice entre tout le monde et personne invite à interroger cette dépendance, sans établir que nul ne puisse jamais acquérir une estime de soi solide."}],"uses":[{"subject":"Avons-nous besoin d’autrui pour avoir conscience de nous-mêmes ?","function":"Distinguer conscience de soi et validation","reason":"Le besoin d’approbation montre un rôle du regard d’autrui, sans prouver que toute conscience de soi dépende de ses éloges.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"},{"subject":"La conscience de soi est-elle trompeuse ?","function":"Interroger l’image que l’on se donne","reason":"Le sentiment d’assurance peut masquer à soi-même une demande de reconnaissance.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=20","sourceLabel":"Recueil académique · p. 20"}]},{"id":"cioran-le-corps-revele-par-l-epreuve","code":"C10","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le corps révélé par l’épreuve","work":"La Chute dans le temps","locator":"« Sur la maladie »","quote":"Pour que la conscience atteigne à une certaine intensité, il faut que l’organisme pâtisse et même qu’il se désagrège : la conscience, à ses débuts, est conscience des organes.","notions":["conscience","nature","liberte"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le corps devient-il plus présent à la conscience lorsqu’il cesse de fonctionner sans difficulté ?"},{"function":"L’affirmation","sentence":"Cioran rapporte l’intensification de la conscience à l’épreuve d’un organisme qui souffre."},{"function":"Les concepts","sentence":"La conscience des organes désigne ici leur présence insistante dans notre expérience, plutôt qu’un savoir anatomique complet."},{"function":"La raison","sentence":"Ce qui se faisait oublier dans une activité aisée retient notre attention dès qu’une gêne ou une douleur interrompt cette activité."},{"function":"L’exemple","sentence":"Une difficulté à respirer peut ainsi rendre sensible une fonction que nous accomplissions sans y penser."},{"function":"La portée","sentence":"Ce diagnostic polémique éclaire une expérience du corps empêché, sans établir que la souffrance soit nécessaire à toute conscience ni que cette conscience accrue rende plus libre."}],"uses":[{"subject":"Peut-on penser sans sentir ?","function":"Montrer un enracinement corporel de la réflexion","reason":"Une modification corporelle peut devenir le point de départ d’une attention et d’une réflexion sur soi.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=18","sourceLabel":"Recueil académique · p. 18"},{"subject":"La conscience est-elle source de liberté ou de contrainte ?","function":"Distinguer conscience accrue et pouvoir accru","reason":"Mieux sentir sa dépendance corporelle ne donne pas nécessairement les moyens de la surmonter.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=19","sourceLabel":"Recueil académique · p. 19"}]},{"id":"cioran-la-creation-et-la-clairvoyance","code":"C11","author":"Cioran","authorRole":"Écrivain et penseur","title":"La création et la clairvoyance","work":"La Chute dans le temps","locator":"« Les dangers de la sagesse »","quote":"Produire, « créer », c’est s’interdire la clairvoyance, c’est avoir le courage ou le bonheur de ne pas percevoir le mensonge de la diversité, le caractère trompeur du multiple.","notions":["art","verite"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Une lucidité qui relativise toute apparence laisse-t-elle encore un motif de créer ?"},{"function":"L’affirmation","sentence":"Cioran présente la création comme un engagement dans des différences qu’une sagesse détachée tend à dissoudre."},{"function":"Les concepts","sentence":"La clairvoyance désigne ici ce détachement radical, tandis que la diversité est le monde des formes et des conflits qui fournit ses matériaux à l’artiste."},{"function":"La raison","sentence":"Créer suppose d’accorder assez d’importance à ces différences pour les explorer plutôt que les ramener toutes au même néant."},{"function":"L’exemple","sentence":"Un romancier travaille les conflits de ses personnages parce qu’il consent à prendre au sérieux leurs attachements singuliers."},{"function":"La portée","sentence":"Cette provocation oppose deux rapports au monde, sans démontrer que l’artiste doive ignorer son métier ou renoncer à tout examen critique de son œuvre."}],"uses":[{"subject":"L’art est-il une forme de connaissance ?","function":"Distinguer attention créatrice et détachement","reason":"Une œuvre peut explorer des apparences auxquelles une certaine sagesse refuserait de s’attacher.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=6","sourceLabel":"Recueil académique · p. 6"},{"subject":"Faut-il préférer la vérité au bonheur ?","function":"Interroger les effets d’une lucidité radicale","reason":"Examiner si dévoiler toute apparence comme trompeuse peut détruire aussi des motifs de vivre et de créer.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"L’artiste sait-il ce qu’il fait ?","function":"II.3 : mettre à l’épreuve une création sans lucidité","reason":"Confronter le détachement radical visé par Cioran à la lucidité du travail artistique : refuser une sagesse qui dissout les apparences n’interdit pas les choix et les corrections.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517046.pdf#page=2","sourceLabel":"Bac 2026 · Amérique du Nord","a20":"philosophie-bac-2026-l-artiste-sait-il-ce-qu-il-fait.html","a20Step":"II.3","a20Status":"Insertion possible comme thèse à discuter après lecture de la copie ; citation absente du modèle."}]},{"id":"cioran-l-avenir-deja-passe","code":"C12","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’avenir déjà passé","work":"La Chute dans le temps","locator":"« Tomber du temps »","quote":"Vivre, c’est subir la magie du possible ; mais lorsqu’on perçoit dans le possible même du révolu à venir, tout devient virtuellement passé, et il n’y a plus de présent ni de futur.","notions":["temps","conscience"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Que devient le présent si nous regardons chaque possibilité comme déjà révolue ?"},{"function":"L’affirmation","sentence":"Cioran décrit une expérience où l’anticipation de la disparition retire aux instants leur ouverture."},{"function":"Les concepts","sentence":"Le possible est ce qui peut encore advenir, tandis que le révolu désigne ce qui est achevé et ne peut plus être modifié."},{"function":"La raison","sentence":"Traiter par avance un projet comme un souvenir détruit l’attente qui permettrait de s’y engager et d’en éprouver la nouveauté."},{"function":"L’exemple","sentence":"Imaginer une rencontre uniquement comme ce qui sera bientôt terminé peut empêcher d’être disponible à ce qui s’y passe."},{"function":"La portée","sentence":"La formule éclaire ainsi une manière de perdre le présent, sans affirmer que le temps physique cesse de s’écouler ni que toute anticipation soit paralysante."}],"uses":[{"subject":"Est-il possible de vivre au présent ?","function":"Distinguer présence chronologique et disponibilité","reason":"Être dans l’instant ne suffit pas si l’on le considère déjà comme un passé clos.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"Mesurer le temps, est-ce en faire l’expérience ?","function":"Distinguer mesure et temps vécu","reason":"Un même intervalle mesuré peut être vécu comme une ouverture ou comme une disparition déjà accomplie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=66","sourceLabel":"Recueil académique · p. 66"}]},{"id":"cioran-le-malaise-avant-la-faute","code":"C13","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le malaise avant la faute","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"La malédiction qui nous accable pesait déjà sur notre premier ancêtre, bien avant qu’il se tournât vers l’arbre de la connaissance.","notions":["bonheur","religion"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Pourquoi désirer quitter un bonheur dont on disposerait déjà ?"},{"function":"L’affirmation","sentence":"Cioran situe le malaise d’Adam avant la transgression, au cœur même du paradis."},{"function":"Les concepts","sentence":"La malédiction désigne ici une insatisfaction constitutive, et le premier ancêtre est la figure biblique par laquelle cette condition humaine est interrogée."},{"function":"La raison","sentence":"Si Adam cède si facilement à la tentation, c’est, selon cette lecture, que la paix disponible ne suffisait déjà pas à le satisfaire."},{"function":"L’exemple","sentence":"Un repos longtemps désiré peut ainsi laisser paraître une nouvelle impatience lorsqu’aucun obstacle extérieur ne trouble plus notre vie."},{"function":"La portée","sentence":"La relecture du mythe interroge notre aptitude au bonheur, sans établir que toute insatisfaction soit universelle ni que cette interprétation soit le sens unique de la Genèse."}],"uses":[{"subject":"Le bonheur est-il inaccessible à l’homme ?","function":"Déplacer la difficulté vers notre rapport au bonheur","reason":"L’obstacle peut tenir à notre incapacité de nous satisfaire d’un bonheur présent, et pas seulement aux événements qui nous en privent.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"},{"subject":"Un bonheur sans illusion est-il concevable ?","function":"Interroger l’idéal d’une innocence heureuse","reason":"La fiction d’un paradis antérieur au savoir peut elle-même dissimuler une inquiétude déjà présente.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-connaitre-et-perdre-la-familiarite-du-monde","code":"C14","author":"Cioran","authorRole":"Écrivain et penseur","title":"Connaître et perdre la familiarité du monde","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Le désir de connaître, empreint de perversité et de corruption, plus il nous tient, plus il nous rend incapables de demeurer à l’intérieur de quelque réalité que ce soit.","notions":["raison","verite","bonheur"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le désir de savoir nous rapproche-t-il toujours du monde dans lequel nous vivons ?"},{"function":"L’affirmation","sentence":"Cioran décrit une connaissance qui éloigne de la participation immédiate aux choses à mesure qu’elle cherche à les analyser."},{"function":"Les concepts","sentence":"Demeurer à l’intérieur d’une réalité signifie ici y être engagé sans la tenir constamment à distance comme un objet à examiner."},{"function":"La raison","sentence":"Dans sa relecture de la Genèse, la curiosité rompt une familiarité et pousse l’homme vers de nouvelles questions plutôt que vers un repos définitif."},{"function":"L’exemple","sentence":"Analyser sans cesse les raisons d’une joie peut modifier cette joie et empêcher de s’y abandonner."},{"function":"La portée","sentence":"Le vocabulaire de la faute dramatise cette rupture, sans démontrer que tout savoir soit nuisible ni que toute analyse interdise de vivre."}],"uses":[{"subject":"Le désir de savoir est-il naturel ?","function":"Distinguer élan spontané et accord avec la nature","reason":"Le désir de connaître peut être puissant tout en nous éloignant, selon Cioran, d’une adhésion immédiate à notre condition.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=48","sourceLabel":"Recueil académique · p. 48"},{"subject":"La connaissance peut-elle nuire au bonheur ?","function":"Analyser le prix d’une mise à distance","reason":"Le regard qui examine peut défaire certaines évidences dont une expérience heureuse se nourrissait.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=15","sourceLabel":"Recueil académique · p. 15"},{"subject":"Faut-il être inconscient pour être heureux ?","function":"I.2 : renforcer l’attrait de l’insouciance","reason":"Le désir d’analyse peut rompre une familiarité heureuse et nourrir l’inquiétude ; cette première réponse reste à confronter aux dangers que l’ignorance ne supprime pas.","source":"https://www.education.gouv.fr/sites/default/files/document/baccalaureat-general-2026-philosophie-517430.pdf#page=2","sourceLabel":"Bac 2026 · Asie","a20":"philosophie-bac-2026-faut-il-etre-inconscient-pour-etre-heureux.html","a20Step":"I.2","a20Status":"Insertion possible après lecture de la copie, en complément de Pascal, sans assimiler les deux arguments."}]},{"id":"cioran-la-conscience-de-notre-fragilite","code":"C15","author":"Cioran","authorRole":"Écrivain et penseur","title":"La conscience de notre fragilité","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"L’inorganique se suffit à lui-même ; l’organique est dépendant, menacé, instable ; le conscient est quintessence de caducité.","notions":["conscience","nature","temps"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La conscience de notre condition ajoute-t-elle une épreuve à notre fragilité physique ?"},{"function":"L’affirmation","sentence":"Cioran présente la conscience comme une intensification de la précarité propre au vivant."},{"function":"Les concepts","sentence":"La caducité désigne le caractère périssable, tandis que la quintessence en figure ici la concentration extrême."},{"function":"La raison","sentence":"Dans ce passage, l’homme éprouve sa dépendance et anticipe sa mort, au lieu de seulement subir les limites de son organisme."},{"function":"L’exemple","sentence":"Prévoir la disparition future d’un bonheur peut ainsi troubler une joie qui n’est pas encore menacée dans le présent."},{"function":"La portée","sentence":"Cette gradation éclaire le poids de la mortalité connue, sans décrire scientifiquement tous les vivants ni établir que toute conscience exclue la joie."}],"uses":[{"subject":"La mort est-elle un obstacle au bonheur ?","function":"Distinguer mortalité et anticipation de la mort","reason":"La conscience d’une fin peut peser sur le présent avant que cette fin survienne.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=17","sourceLabel":"Recueil académique · p. 17"},{"subject":"Peut-on être pleinement homme sans penser à la mort ?","function":"Interroger la place de la finitude dans la conscience","reason":"Le passage lie la singularité humaine au savoir de sa précarité, dont il faut examiner aussi les effets sur la vie.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=137","sourceLabel":"Recueil académique · p. 137"}]},{"id":"cioran-le-savoir-nous-precipite-dans-le-temps","code":"C16","author":"Cioran","authorRole":"Écrivain et penseur","title":"Le savoir nous précipite dans le temps","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Précipités par le savoir dans le temps, nous fûmes du même coup dotés d’un destin.","notions":["temps","conscience","religion"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Comment le savoir pourrait-il nous faire entrer dans un temps où nous vivons déjà ?"},{"function":"L’affirmation","sentence":"Cioran interprète la sortie du paradis comme l’apparition d’une existence consciente de son devenir."},{"function":"Les concepts","sentence":"Le temps désigne ici l’expérience de la perte et des possibles, tandis que le destin donne à notre vie la forme d’une histoire orientée vers sa fin."},{"function":"La raison","sentence":"Le savoir rompt l’adhésion innocente au présent en faisant apparaître ce qui pourrait arriver et ce qui ne reviendra plus."},{"function":"L’exemple","sentence":"Savoir qu’une rencontre peut être la dernière transforme un moment ordinaire en événement chargé d’attente et de regret."},{"function":"La portée","sentence":"Cette lecture philosophique du mythe distingue le temps vécu de la simple durée, sans prétendre que les êtres privés de ce savoir échappent au changement physique."}],"uses":[{"subject":"Est-il possible d’échapper au temps ?","function":"Distinguer durée physique et conscience du devenir","reason":"Le paradis figure une innocence soustraite à l’expérience inquiète de la perte, plutôt qu’une simple absence de changement.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=65","sourceLabel":"Recueil académique · p. 65"},{"subject":"La conscience de ce que nous sommes peut-elle faire obstacle à notre bonheur ?","function":"Montrer le poids de l’anticipation","reason":"La conscience de notre avenir et de notre fin peut troubler l’adhésion au présent, sans suffire à condamner toute lucidité.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=13","sourceLabel":"Recueil académique · p. 13"}]},{"id":"cioran-l-outil-et-la-faiblesse-humaine","code":"C17","author":"Cioran","authorRole":"Écrivain et penseur","title":"L’outil et la faiblesse humaine","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"N’éprouvant nul besoin d’ajouter à sa force, qui est réelle, un fauve ne s’abaisse pas à l’outil.","notions":["technique","nature"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"La puissance technique prouve-t-elle une force naturelle supérieure ?"},{"function":"L’affirmation","sentence":"Cioran renverse cette interprétation en présentant l’outil comme une compensation dont l’animal puissant n’aurait pas besoin."},{"function":"Les concepts","sentence":"La force réelle désigne ici une puissance corporelle disponible, tandis que l’outil ajoute des moyens artificiels à un organisme insuffisamment armé."},{"function":"La raison","sentence":"Dans le récit de la sortie du paradis, l’inadaptation humaine devient ainsi le ressort d’une conquête toujours plus ambitieuse."},{"function":"L’exemple","sentence":"Un instrument de coupe permet à une main de réaliser ce qu’elle ne pourrait accomplir par sa seule force."},{"function":"La portée","sentence":"Le verbe s’abaisser exprime une provocation qui renverse notre hiérarchie habituelle, sans fournir une classification scientifique des animaux ni prouver que tout outil soit dégradant."}],"uses":[{"subject":"La technique nous libère-t-elle de la nature ?","function":"Retrouver une dépendance dans la puissance acquise","reason":"L’invention technique peut répondre à des limites naturelles plutôt que nous en rendre absolument indépendants.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=47","sourceLabel":"Recueil académique · p. 47"},{"subject":"La technique naît-elle de nos besoins ou de nos rêves ?","function":"Relier compensation et ambition","reason":"Un manque initial peut susciter des moyens dont le développement dépasse ensuite la seule satisfaction du besoin.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"}]},{"id":"cioran-devenir-n-est-pas-progresser","code":"C18","author":"Cioran","authorRole":"Écrivain et penseur","title":"Devenir n’est pas progresser","work":"La Chute dans le temps","locator":"« L’Arbre de vie »","quote":"Devenir et progrès sont notions en apparence voisines, en fait divergentes.","notions":["technique","temps","raison"],"edition":"La Chute dans le temps (première publication)","publisher":"Gallimard","editionYear":"1964","originalLanguage":"français","translator":null,"commentary":[{"function":"Le problème","sentence":"Le simple fait de changer nous conduit-il nécessairement vers un état meilleur ?"},{"function":"L’affirmation","sentence":"Cioran refuse d’identifier le devenir à un progrès."},{"function":"Les concepts","sentence":"Le devenir désigne une transformation, tandis que le progrès suppose un critère permettant de juger cette transformation meilleure."},{"function":"La raison","sentence":"Une suite de nouveautés ne justifie donc pas à elle seule une confiance dans l’amélioration de la condition humaine."},{"function":"L’exemple","sentence":"Une machine plus puissante peut faciliter une tâche tout en augmentant des dépendances ou des destructions."},{"function":"La portée","sentence":"Cette distinction oblige à évaluer les transformations plutôt qu’à célébrer leur nouveauté, sans prouver que toute amélioration soit impossible ni que tout changement soit une dégradation."}],"uses":[{"subject":"Faut-il voir dans l’histoire humaine un progrès constant ?","function":"Distinguer succession et amélioration","reason":"L’enchaînement des changements n’établit pas leur valeur ni leur direction vers un mieux.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=52","sourceLabel":"Recueil académique · p. 52"},{"subject":"Le progrès de l’humanité se réduit-il au progrès technique ?","function":"Distinguer puissance des moyens et valeur des fins","reason":"Une efficacité accrue ne suffit pas à établir une amélioration du bonheur, de la justice ou de la liberté.","source":"https://pedagogie.ac-montpellier.fr/sites/default/files/ressources/Sujets-Bac-Philo_Dissertations_1996-2025.pdf#page=60","sourceLabel":"Recueil académique · p. 60"}]}]};
